class IntGraph(n: Int) {
    case class Node(value: Int, cost: Int);
    val matrix: Array[List[Node]] = new Array[List[Node]](n).map( e => Nil);

    override def toString(): String = {
        matrix.zipWithIndex.foldLeft[List[String]](Nil) { (list, e) =>
            val nodes = e._1.map( n => n.value.toString + "(" + n.cost.toString + ")"); 
            e._2.toString + " -> " + nodes.mkString(", ") :: list;
        }.reverse.mkString("\n");
    }

    def add(src: Int, dst: Int, cost: Int): Unit = matrix(src) = Node(dst, cost) :: matrix(src);

    def mst(): (Array[Int], Array[Int]) = {
        val colors = new Array[Int](n); // 0 : 未探索, 1 : 追加候補, 2 : 追加済み
        val parents = new Array[Int](n);
        val distances = new Array[Int](n).map( e => Int.MaxValue);
        val pq = new PriorityQueue[Node](n * n)(Ordering.by((e: Node) => e.cost).reverse);
        def _mst(): Unit = {
            pq.dequeue match {
                case None => ();
                case Some(Node(minValue, minCost)) => {
                    if (colors(minValue) != 2) {
                        colors(minValue) = 2;
                        matrix(minValue).foreach { e =>
                            if (e.cost < distances(e.value) && colors(e.value) != 2) {
                                colors(e.value) = 1;
                                parents(e.value) = minValue;
                                distances(e.value) = e.cost;
                                pq.enqueue(e);
                            }
                        }
                    }
                    _mst;
                }
            }
        }
        parents(0) = -1;
        distances(0) = 0;
        pq.enqueue(Node(0, distances(0)));
        _mst;
        (distances, parents);
    }
}

class PriorityQueue[A](len: Int)(implicit ord: Ordering[A]) {
    import ord._;
    private val heap = new ArraySeq[A](len);
    var size = 0;

    def isEmpty: Boolean = size == 0;

    def isFull: Boolean = size == len;

    def enqueue(e: A): Unit = {
        def _enqueue(curr: Int): Unit = {
            // if (curr % 2 == 0) right else left
            val parent = if (curr % 2 == 0) (curr - 2) / 2 else (curr - 1) / 2; 
            if (parent >= 0 && heap(curr) > heap(parent)) {
                swap(curr, parent);
                _enqueue(parent);
            }
        }
        if (!isFull) {
            heap(size) = e;
            _enqueue(size);
            size += 1;
        }
    }

    def dequeue(): Option[A] = {
        if (isEmpty) {
            None;
        } else {
            val top = heap(0);
            size -= 1;
            heap(0) = heap(size);
            heapify(0);
            Some(top);
        }
    }

    private def heapify(curr: Int): Unit = {
        if (curr < size) {
            val left = curr * 2 + 1;
            val right = curr * 2 + 2;
            if (right < size) {
                val maxIdx = max(curr, left, right);
                if (curr < maxIdx) {
                    swap(curr, maxIdx);
                    heapify(maxIdx);
                }
            } else if (left < size && heap(left) > heap(curr)) {
                swap(curr, left);
            }
        }
    }

    private def max(curr: Int, left: Int, right: Int): Int = {
        if (heap(curr) > heap(left)) {
            if (heap(right) > heap(curr)) right else curr;
        } else {
            if (heap(right) > heap(left)) right else left;
        }
    }

    private def swap(a: Int, b: Int): Unit = {
        val tmp = heap(a);
        heap(a) = heap(b);
        heap(b) = tmp;
    }
}

import scala.collection.mutable.ArrayBuffer

object Main {

  def main(args: Array[String]): Unit = {

    class UnionSet(par: Array[Int]) {
      def root(x: Int): Int =
        if (par(x) == x) x
        else {
          par(x) = root(par(x))
          par(x)
        }
      def unite(x: Int, y: Int): Unit = {
        val rx = root(x)
        val ry = root(y)
        if (rx != ry)
          par(rx) = ry
      }
      def same(x: Int, y: Int): Boolean =
        root(x) == root(y)
    }
    object UnionSet {
      def apply(n: Int): UnionSet =
        new UnionSet(Array.range(0, n))
    }

    val sc = new java.util.Scanner(System.in)

    val N = sc.nextInt()
    val W = Array.fill(N, N)(sc.nextInt())

    val _E = new ArrayBuffer[(Int, Int)]() // (辺(u,v), 重みw)

    for {
      i <- 0 until N
      j <- 0 until N
      if W(i)(j) >= 0
    } _E.append((i, j))

    val E: List[(Int, Int)] = _E.sortBy(e => W(e._1)(e._2)).toList // 辺(軽い順)

    // 最初, 全ての頂点は別の木として初期化する
    val unionset = UnionSet(N)
    var count = 0
    // 軽い辺から見ていき
    E foreach { e =>
      val (u, v) = e
      // u, v が別の木ならば, これは軽い辺なので安全に追加できる.
      if (!unionset.same(u, v)) {
        unionset.unite(u, v)
        count += W(u)(v)
      }
    }

    // 入力が連結グラフであることから,最終的に出来上がった木は1本となり, これが最小全域木である
    // 加えた辺の重さの合計が最小全域木の重さの合計
    println(count)
  }

}

import scala.io.StdIn.{readLine,readInt}
import scala.collection.mutable.ArrayBuffer

object Main {
  def main(args:Array[String]) = {
    val n = readInt
    val b = new ArrayBuffer[Int]
    val g = for(i<-0 until n) yield {
      readLine.trim.split(" ").map(_.toInt)
    }

    var v = 0
    var total = 0
    b += v

    while(b.length < g.length) {
      var min = Int.MaxValue
      v = 0
      for(e <- b) {
        val list = (for(i<-0 until g(e).length if !b.contains(i)) yield (g(e)(i),i)).filter(_._1 != -1)
        if(list.length > 0) {
          val listMin = list.min
          if(listMin._1<min) {
            min = listMin._1
            v = listMin._2
          }
        }
      }
      total += min
      b += v
    }
    println(total)
  }
}

