class PriorityQueue[A](size: Int)(implicit m: ClassTag[A], ord: Ordering[A]) {
    import ord._;
    private[this] val pq = m.newArray(size);
    private[this] var ptr = 0;

    def enqueue(e: A): Unit = {
        def go(curr: Int): Unit = {
            val parent = if (curr % 2 == 1) (curr - 1) / 2 else (curr - 2) / 2;
            if (parent >= 0 && pq(curr) > pq (parent)) {
                swap(curr, parent);
                go(parent);
            }
        }
        pq(ptr) = e;
        go(ptr);
        ptr += 1;
    }
    def dequeue(): A = {
        if (ptr == 0) {
            throw new NoSuchElementException("value is not found");
        } else if (ptr == 1) {
            ptr = 0;
            pq(0);
        } else {
            ptr -= 1;
            val ret = pq(0);
            pq(0) = pq(ptr);
            heapify(0);
            ret;
        }
    }

    def dequeueOption(): Option[A] = {
        try {
            Option(dequeue());
        } catch {
            case e: Exception => None;
        }
    }

    private def heapify(curr: Int): Unit = {
        val left = curr * 2 + 1;
        val right = curr * 2 + 2;
        if (right < ptr) {
            val maxIdx = max(curr, left, right);
            if (curr != maxIdx) {
                swap(curr, maxIdx);
                heapify(maxIdx);
            }
        } else if (left < ptr) {
            if (pq(left) > pq(curr)) swap(curr, left);
        }
    }

    private def max(a: Int, b: Int, c: Int): Int = {
        if (pq(a) > pq(b)) {
            if (pq(a) > pq(c)) a else c;
        } else {
            if (pq(b) > pq(c)) b else c;
        }
    }

    private def swap(a: Int, b: Int): Unit = {
        val tmp = pq(a);
        pq(a) = pq(b);
        pq(b) = tmp;
    }
}

