object Main {

  def main(args: Array[String]): Unit = {

    class UnionFind(par: Array[Int]) {

      def root(x: Int): Int =
        if (par(x) == x) x
        else {
          par(x) = root(par(x))
          par(x)
        }

      def unite(x: Int, y: Int): Unit = {
