        root(x) == root(y)

    }

    object UnionFind {

      def apply(n: Int): UnionFind =
        new UnionFind(Array.range(0, n))

    }

    val sc = new java.util.Scanner(System.in)

    val N = sc.nextInt()
    val A = Array.fill(N, N)(sc.nextInt())

    val _E = new ArrayBuffer[((Int, Int),Int)]() // (辺(u,v), 重みw)
    (0 until N) foreach { i =>
      (0 until N) foreach { j =>
        if (A(i)(j) >= 0) {
          _E.append(((i, j), A(i)(j)))
        }
      }
    }
    val E: List[((Int, Int), Int)] = _E.sortBy(_._2).toList // 辺(軽い順)

    // 最初, 全ての頂点は別の木として初期化する
    val unionset = UnionFind(N)
    var count = 0
    // 軽い辺から見ていき
    E foreach { e =>
      val ((u, v), w) = e
      // u, v が別の木ならば, これは軽い辺なので安全に追加できる.
      if (!unionset.same(u, v)) {
        unionset.unite(u, v)
        count += w
      }
    }

    // 入力が連結グラフであることから,最終的に出来上がった木は1本となり, これが最小全域木である
    // 加えた辺の重さの合計が最小全域木の重さの合計
    println(count)
  }

}

