    val in = io.Source.stdin.getLines.map(_.trim.split(" ").map(_.toInt))
    val n = in.next.head
    val t = (0 to n-1).toArray
    val d = in.toSeq
    val es = (for (i <- (0 to n-2); j <- (i+1 to n-1) if d(i)(j) != -1) yield (i, j, d(i)(j))).sortBy(_._3)
    var cost = 0
    val find: Int => Int = m => if(t(m) == m) m else {t(m) = find(t(m)); t(m)}
    val unite: (Int, Int) => Unit = (x, y) => {
        val _x = find(x)
        val _y = find(y)
        if(_x != _y) t(_x) = _y
    }

    es.foreach(e => if (find(e._1) != find(e._2)) {unite(e._1, e._2); cost += e._3})
