pair<int, pair<int, int> > findMinEdge(){
    int min = INFINITY;
    pair<int, int> r;
    set<int >::iterator itr;
    for (itr = T.begin(); itr != T.end(); itr++){
        for (set<int>::iterator itr1 = V_T.begin(); itr1 != V_T.end(); itr1++){
            if (graph[*itr][*itr1] < min){
                min = graph[*itr][*itr1];
                r = make_pair(*itr, *itr1);
            }
        }
    }
    return make_pair(min, r);
}

void findMinSpanTree(){
    while (!V_T.empty()){
        pair<int, pair<int, int> > v = findMinEdge();
        sum += v.first;
        parent[v.second.second] = v.second.first;
        T.insert(v.second.second);
        V_T.erase(V_T.find(v.second.second));
    }
}

