{
	cin >> n;

	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			int temp;
			cin >> temp;

			if (temp == -1) {
				grid[i][j] = INF;
			}
			else {
				grid[i][j] = temp;
			}
		}
	}

	cout << prim() << endl;

	return 0;
}

#include <iostream>
using namespace std;
static const int MAX = 100;
static const int INFTY = (1 << 21);
static const int WHITE = 0;
static const int GRAY = 1;
static const int BLACK = 2;

int n, M[MAX][MAX];

int prim()
{
  int u, mincost;
  int d[MAX], p[MAX], color[MAX];

  // 初期化
  for (int i = 0; i < n; i++)
  {
    d[i] = INFTY;
    p[i] = -1;
    color[i] = WHITE;
  }

  // 頂点0から始めるため
  d[0] = 0;

  while (true)
  {
    mincost = INFTY;
    u = -1;
    // 初回は頂点0が選ばれる
    // 隣接する頂点を探す処理で、重みdが設定されていれば
    // 最小コストの頂点uが選ばれる
    for (int i = 0; i < n; i++)
    {
      if (mincost > d[i] && color[i] != BLACK)
      {
        u = i;
        mincost = d[i];
      }
    }

    if (u == -1)
    {
      break;
    }

    // 最小全域木の頂点に選ばれた
    color[u] = BLACK;

    for (int v = 0; v < n; v++)
    {
      if (color[v] != BLACK && M[u][v] != INFTY)
      {
        // 最小全域木に選ばれていないかつ、uに対して辺がある頂点v
        if (d[v] > M[u][v])
        {
          // 頂点uとvの辺の重みに更新する
          d[v] = M[u][v];
          p[v] = u;
          color[v] = GRAY;
        }
      }
    }
  }

  // 最小全域木の辺の重みの総和
  int sum = 0;
  for (int i = 0; i < n; i++)
  {
    if (p[i] != -1)
    {
      sum += M[i][p[i]];
    }
  }

  return sum;
}

int main()
{
  cin >> n;

  for (int i = 0; i < n; i++)
  {
    for (int j = 0; j < n; j++)
    {
      int e;
      cin >> e;
      M[i][j] = (e == -1) ? INFTY : e;
    }
  }

  cout << prim() << endl;

  return 0;
}

