#include <iostream>

#define MAX_N 101
#define INFTY 20000
#define NIL -1

enum Color {
    White,
    Glay,
    Black,
};

using namespace std;

int n;
int w[MAX_N][MAX_N];
int d[MAX_N], p[MAX_N];
Color color[MAX_N];

int min(int x, int y) {
    if(x < y) return x;
    return y;
}

int solve() {
    d[0] = 0;

    while(true) {
        int u = NIL, c = INFTY;

        for(int i=0; i<n; i++) {
            if(d[i] < c && color[i] != Black) {
                u = i;
                c = d[i];
            }
        }

        if(u == NIL)
            break;

        color[u] = Black;

        for(int i=0; i<n; i++) {
            if(color[i] != Black && w[u][i] != INFTY) {
                if(d[i] > w[u][i]) {
                    d[i] = w[u][i];
                    p[i] = u;
                    color[i] = Glay;
                }
            }
        }
    }


    int tc = 0;
    for(int i=0; i<n; i++) {
        if(color[i] == Black) {
            tc += w[i][p[i]];
        }
    }
    return tc;
}

int main() {
    for (int i = 0; i < MAX_N; i++) {
        d[i] = INFTY;
        p[i] = INFTY;
        color[i] = White;
        for (int j = 0; j < MAX_N; j++)
            w[i][j] = INFTY;
    }

    int p;
    cin >> n;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> p;
            w[i][j] = (p == -1) ? INFTY : p;
        }
    }

    cout << solve() << endl;
}

#include <bits/stdc++.h>
using namespace std;

#define N_MAX 100

int M[N_MAX][N_MAX];

int main(){

  int n;
  scanf("%d", &n);

  for(int i=0; i<n*n; i++){
    scanf("%d", &M[i/n][i%n]);
  }

  /*
   * Find Mininum Spanning Tree using
   * Prim's Algorithm
  */
  vector<bool> is_belong_to_mst(n, false);
  is_belong_to_mst.at(0) = true;
  int total_cost = 0;
  for(int i=1; i<n; i++){
    // get t and adj
    vector<int> t;
    vector<int> adj;
    for(int i=0; i<n; i++){
      if(is_belong_to_mst.at(i)) t.push_back(i);
      else adj.push_back(i);
    }

    int min_cost = INT_MAX;
    int next_t = 0;
    for(int i=0; i<t.size(); i++){
      for(int j=0; j<adj.size(); j++){
        if(M[t.at(i)][adj.at(j)] != -1 && M[t.at(i)][adj.at(j)] < min_cost){
          min_cost = M[t.at(i)][adj.at(j)];
          next_t = adj.at(j);
        }
      }
    }

