#define CANDIDATE 2

int n;

int prim(vvi &g) {
  vi d(n, INT_MAX), s(n, WHITE), p(n, -1); 
  d[0] = 0;

  int total = 0;
  while (true) {
    int min_cost = INT_MAX, u;
    rep(i, n) {
      if (s[i] != VISITED && d[i] < min_cost) {
        min_cost = d[i];
        u = i;
      }
    }

    if (min_cost == INT_MAX) break;

    s[u] = VISITED;
    if (p[u] != -1) total += g[p[u]][u];

    rep(v, n) {
      if (s[v] != VISITED && g[u][v] != -1) {
        if (g[u][v] < d[v]) {
          d[v] = g[u][v];
          p[v] = u;
          s[v] = CANDIDATE;
        }
      }
    }
  }

  return total;
}

