// Edge {{{
template <class Weight>
struct Edge {
    size_t from, to;
    Weight weight;

    Edge() {}
    Edge(size_t from, size_t to, Weight weight = 1) :
        from(from), to(to), weight(weight)
    {}

    bool operator<(const Edge &rhs) const {
        return weight < rhs.weight;
    }

    bool operator>(const Edge &rhs) const {
        return weight > rhs.weight;
    }

    operator size_t() const {
        return to;
    }
};
// }}}

// UnionFind {{{
struct UnionFind {
    vector<int> tree;
    explicit UnionFind(const size_t n) : tree(n + 1, -1) {}

    size_t size(size_t i) {
        return -tree[root(i)];
    }

    size_t root(size_t x) {
        return (tree[x] < 0) ? x : tree[x] = root(tree[x]);
    }

    bool connected(size_t x, size_t y) {
        return root(x) == root(y);
    }

    bool unite(size_t x, size_t y) {
        x = root(x);
        y = root(y);
        if (x == y) {
            return false;
        } else {
            tree[x] += tree[y];
            tree[y] = x;
            return true;
        }
    }
};
// }}}

// kruskal {{{
template <class Weight>
Weight kruskal(vector<Edge<Weight>> &es) {
    const size_t V = es.size();
    UnionFind uf(V);
    Weight minCost = 0;

    sort(es.begin(), es.end());

    for (const auto &e: es) {
        if (uf.unite(e.from, e.to)) {
            minCost += e.weight;
        }
    }

    return minCost;
}
// }}}

