		height.resize(size, 0);
		REP(i, size) {
			parent[i] = i;
		}
	}
	int find(int x) {
		if (parent[x] == x) {
			return x;
		}
		return parent[x] = find(parent[x]);
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (height[x] < height[y]) parent[x] = y;
		else parent[y] = x;
		if (height[x] == height[y]) ++height[x];
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
};

struct Edge {
	int from, to, cost;
	Edge(int f, int t, int c) : from(f), to(t), cost(c) {};
};
bool operator<(const Edge& l, const Edge& r) {
	return l.cost < r.cost;
}

signed main() {
	INIT;
	VAR(int, n);
	MAT(int, a, n, n);
	UnionFind uf(n);
	std::priority_queue<Edge> pq;
	REP(i, n) FOR(j, i + 1, n) {
		if (a[i][j] != -1) {
			pq.push(Edge(i, j, -a[i][j]));
		}
	}
	int ans = 0;
	while (!pq.empty()) {
		Edge now = pq.top(); pq.pop();
		if (uf.same(now.from, now.to)) continue;
		uf.unite(now.from, now.to);
		ans -= now.cost;
	}
	OUT(ans)BR;
	return 0;
}

