  for(int i = 0; i < n; i++) {
    for(int j = 0; j < n; j++) {
	cin >> cost;
	if(j > i && cost != -1) {
	  e.cost = cost; e.x = i; e.y = j;
	  Edges.push_back(e);
	}
    }
  }
  sort(Edges.begin(), Edges.end());
  for(int i = 0; i < Edges.size(); i++) {
    if(!is_same_set(Edges[i].x, Edges[i].y)) {
      w += Edges[i].cost;
      unite(Edges[i].x, Edges[i].y);
    }
  }
