int minSpanningTreeRecursive(int16_t currentV, const bool visited[], string inpPath, string &minPath)
{
  assert(0 <= currentV && currentV < gNumOfVertices);

  bool updatedVisited[gNumOfVertices];

  for (int i = 0; i < gNumOfVertices; i++)
    updatedVisited[i] = visited[i];

  updatedVisited[currentV] = true;

  // This function ensures all of elements are unvisited
  vector<int16_t> nextVs = getConnectedVs(currentV, updatedVisited);

  if (nextVs.size() == 0)
  {
    minPath = to_string(currentV);
    return 0;
  }

  int minV = -1;
  int minScore = INT_MAX;
  string currentPath = to_string(currentV);


  if (inpPath.size())
    currentPath = inpPath + " > " + currentPath;

  for (int i = 0; i < nextVs.size(); i++)
  {
    string searchedPath = "";
    const int16_t nextV = nextVs[i];
    const int score = gWeightOfVij[currentV][nextV] + minSpanningTreeRecursive(nextV, updatedVisited, currentPath, searchedPath);

    if (minScore > score)
    {
      minV = nextV;
      minScore = score;
      minPath = searchedPath;
    }

  }

  {
    if (minPath.size())
      minPath = " > " + minPath;

    minPath = to_string(currentV) + minPath;

    DPRINTF("score %d\n", minScore);
    DPRINTF("  %s | %s\n", currentPath.c_str(), minPath.c_str());
  }

  return minScore;
}


int minSpanningTree()
{
  int16_t startV = 0;
  bool visited[gNumOfVertices];

  for (int i = 0; i < gNumOfVertices; i++)
    visited[i] = false;

  string inpPath = "", minPath;

  return minSpanningTreeRecursive(startV, visited, inpPath, minPath);
}


