void MinimumSpanningTree(int start_vertex)
{

    queue<int> Q;

    // 開始点の情報の設定
    Q.push(start_vertex);
    ary_MinEdgeWeight[start_vertex] = 0;

    while( !Q.empty() )
    {
        // キューの先頭要素を取得して, 削除する
        int u = Q.front();
        Q.pop();

        for(int i = 0; i < n; i++)
        {
            // 隣接点を全て検索する
            int weight = ary_graph[u][i];

            if( weight != INV )
            {

                // 辺の重みを設定する
                set_weight(u, i, weight);
                //set_weight(i, u, weight);

                // キューにプッシュする
                Q.push(i);

                // 同じ辺を繰り返し辿らないように無効化する
                ary_graph[u][i] = INV;
                //ary_graph[i][u] = INV;
            }
        }
    }

    return;
}

