            if (status[i] == COMPLETE || G[u][i] == INF) continue;
            if (d[i] > G[u][i]) {
                d[i] = G[u][i];
                parent[i] = u;
                status[i] = VISITED;
            }
        }
    }

    int sum = 0;
    for (int i = 0; i < n; i++) {
        if (parent[i] != -1) sum += G[i][parent[i]];
    }

    return sum;
}

