    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> a;
            if (a == -1) G[i][j] = INF;
            else G[i][j] = a;
        }
    }

    cout << prim() << endl;

    return 0;
}

