struct Edge {
    int from, to, cost;
    Edge(int f, int t, int c) : from(f), to(t), cost(c) { }
    bool operator <(const Edge& e) const {
        return cost < e.cost;
    }
};

struct UnionFind {
    vector<int> data;
    UnionFind(int n) : data(n, -1) { }
    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    void merge(int x, int y) {
        x = root(x), y = root(y);
        if(x != y) {
            data[x] += data[y]; data[y] = x;
        }
    }
};

int main() {
    int N; cin >> N;
    vector<Edge> es;
    for(int i = 0; i < N; i++) {
        for(int j = 0; j < N; j++) {
            int c; cin >> c;
            if(c != -1) {
                es.push_back(Edge(i, j, c));
            }
        }
    }
    sort(es.begin(), es.end());
    UnionFind uf(N);
    int ans = 0;
    for(int i = 0; i < (int)es.size(); i++) {
        int from = es[i].from;
        int to = es[i].to;
        int cost = es[i].cost;
        if(uf.same(from, to)) continue;
        uf.merge(from, to);
        ans += cost;
    }
    cout << ans << endl;
}

