#define INFTY 1000000001

class Graph{
public:
	std::vector< std::vector<int> > A;
	int n;

	Graph(int n);

	void SetEdge(int a, int b, int weight);
	void SortEdge();
	void SortEdge_Rec1(int left, int right);
	void SortEdge_Rec2(int left, int mid, int right);

	int Kruskal();

};

Graph::Graph(int n){;
	this->n = n;
}

void Graph::SetEdge(int a, int b, int weight){
	std::vector<int> x;
	x.push_back(a); x.push_back(b); x.push_back(weight);
	A.push_back(x);
	return;
}

void Graph::SortEdge(){
	SortEdge_Rec1(0, A.size());
}

void Graph::SortEdge_Rec1(int left, int right){
	if (left + 1 < right){
		int mid = (left + right) / 2;
		SortEdge_Rec1(left, mid);
		SortEdge_Rec1(mid, right);
		SortEdge_Rec2(left, mid, right);
	}
}

void Graph::SortEdge_Rec2(int left, int mid, int right){
	int n1 = mid - left;
	int n2 = right - mid;
	std::vector< std::vector<int> > L(n1 + 1);
	for (int i = 0; i < n1; i++) L[i] = A[left + i];
	std::vector< std::vector<int> > R(n2 + 1);
	for (int i = 0; i < n2; i++) R[i] = A[mid + i];
	std::vector<int> x;
	x.push_back(0); x.push_back(0); x.push_back(INFTY);
	L[n1] = x;
	R[n2] = x;
	int i = 0;
	int j = 0;
	for (int k = left; k < right; k++){
		if (L[i][2] <= R[j][2]){
			A[k] = L[i];
			i = i + 1;
		}
		else{
			A[k] = R[j];
			j = j + 1;
		}
	}
}

int Graph::Kruskal(){
	std::vector<int> f(n);
	for (int i = 0; i < n; i++) f[i] = i;
	int branch = 0;

	while (!A.empty()){
		std::vector<int> e = A[0];
		A.erase(A.begin());
		if (f[e[0]] != f[e[1]]){
			int tmp = f[e[1]];
			for (int i = 0; i < n; i++) if (f[i] == tmp) f[i] = f[e[0]];
			branch += e[2];
		}
	}
	return branch;
}

int main(){
	int n, e;
	scanf("%d", &n);
	Graph G(n);
	for (int i = 0; i < n; i++){
		for (int j = 0; j < n; j++){
			scanf("%d", &e);
			if (j >= i && e != -1) G.SetEdge(i, j, e);
		}
	}

	G.SortEdge();

	printf("%d\n", G.Kruskal());

	return 0;
}

