const int INF = 1'000'000'007;
const ll MOD = 998'244'353;

vi par, dep, siz;
int root(int x) {
	if (par[x] == x) return x;
	else return par[x] = root(par[x]);
}
void unite(int x, int y) {
	x = root(x); y = root(y);
	if (x == y) return;
	if (dep[x] > dep[y]) { par[y] = x; siz[x] += siz[y]; }
	else if (dep[x] < dep[y]) { par[x] = y; siz[y] += siz[x]; }
	else { par[y] = x; dep[x] ++; siz[x] += siz[y]; }
}
bool same(int x, int y) { return root(x) == root(y); }
void uf(int NODENUM) {
	par.assign(NODENUM, 0); dep.assign(NODENUM, 0); siz.assign(NODENUM, 1);
	rep(i, NODENUM) par[i] = i;
}
ll kruskal(vector<vpil> cg) {
	using tlii = tuple<ll, int, int>;
	priority_queue<tlii, vector<tlii>, greater<tlii>> pq;
	rep(u, cg.size()) {
		for (pil p : cg[u]) {
			int v; ll d; tie(v, d) = p;
			pq.push(tlii(d, u, v));
		}
	}
	uf(cg.size());
	int cnt = 0; ll dsum = 0;
	while (cnt < cg.size() - 1) {
		int u, v; ll d; tie(d, u, v) = pq.top(); pq.pop();
		if (!same(u, v)) {
			unite(u, v);
			dsum += d;
			cnt++;
		}
	}
	return dsum;
}
ll kruskal(vvi g, vvl dis) {
	vector<vpil> cg(g.size());
	rep(u, g.size()) for (int v : g[u]) cg[u].push_back(pil(v, dis[u][v]));
	return kruskal(cg);
}

