template <class T>
struct Edge {
    int from, to;
    T cost;
    Edge(int from, int to, T cost) : from(from), to(to), cost(cost){};

    bool operator<(const Edge<T>& e) const { return this->cost < e.cost; }
    bool operator>(const Edge<T>& e) const { return this->cost > e.cost; }
};

template <class T = int>
class Graph {
public:
    explicit Graph(int N = 0) : size(N) { path.resize(size); }
    void span(int u, int v, T cost = 1) { path[u].push_back(Edge<T>(u, v, cost)); }
    vector<Edge<T>> operator[](int v) const { return path[v]; }

    int size;
    vector<vector<Edge<T>>> path;
};

class UnionFind {
public:
    vector<int> par, num;

    explicit UnionFind(int N) {
        par.resize(N);
        iota(par.begin(), par.end(), 0);
        num.assign(N, 1);
    }

    int find(int v) {
        return (par[v] == v) ? v : (par[v] = find(par[v]));
    }

    void unite(int u, int v) {
        u = find(u), v = find(v);
        if (u == v) return;

        if (num[u] < num[v]) swap(u, v);
        num[u] += num[v];
        par[v] = u;
    }

    bool same(int u, int v) { return find(u) == find(v); }
    bool ispar(int v) { return v == find(v); }
    int size(int v) { return num[find(v)]; }
};

int main() {
    int N;
    cin >> N;
    vector<Edge<int>> edges;
    for (int u = 0; u < N; ++u) {
        for (int v = 0; v < N; ++v) {
            int c;
            cin >> c;
            if (u < v && c >= 0) edges.push_back(Edge<int>(u, v, c));
        }
    }
    sort(edges.begin(), edges.end());

    int ans = 0;
    UnionFind uf(N);
    for (const auto& e : edges) {
        if (uf.same(e.from, e.to)) continue;
        ans += e.cost;
        uf.unite(e.from, e.to);
    }

    cout << ans << endl;
    return 0;
}

