// W:未訪問
// G:訪問する候補
// B:訪問済み
int W=0,G=1,B=2;
int prim(){
  int u,minv;
  int d[MAXIMUM],p[MAXIMUM],color[MAXIMUM];
  // d[n]:Tに属する頂点と V - T に属する頂点をつなぐ辺の中で重みが最小の辺の重みを記録

  //初期化
  for(int i=0;i<n;i++){
    d[i]=INF;
    p[i]=-1;
    color[i]=W;
  }

  d[0]=0;

  while (1) {
    minv = INF;
    u = -1;
    //訪問済みでない頂点の中で最もコストが低い辺を探す
    for(int i=0;i<n;i++){
      if(minv>d[i] && color[i]!=B){
        u=i;
        minv=d[i];
      }
    }
    // 頂点が見つからなかったら終了
    if(u==-1) break;
    // 頂点を訪問済に
    color[u] = B;
    //訪問済みでないかつ辺がつながっている頂点の中でコストが最小の辺を選択
    for(int v=0;v<n;v++){
      if(color[v]!=B && M[u][v]!=INF){
        if(d[v]>M[u][v]){
          d[v] =M[u][v];
          p[v] =u;
          color[v]=G;
        }
      }
    }
  }

  int sum=0;
  for(int i=0;i<n;i++){
    if(p[i]!=-1) sum+= M[i][p[i]];
  }
  return sum;
}

