class union_find {
  public:
    /// <param name="len">要素数</param>
    union_find(int len) {
      parents = new int[len];
      depths = new int[len];
      for (int i = 0; i < len; i++) parents[i] = i;
      memset(depths, 0, len);
    }
    /// 根を特定　あまり外部から使わない
    int root(int x) {
      return parents[x] == x ? x :
             root(parents[x]);
    }
    /// 2つの要素が同じ木に属すると宣言
    void unite(int x, int y) {
      x = root(x);
      y = root(y);
      if (x == y) return;
      if (depths[x] < depths[y]) parents[x] = y;
      else {
        parents[y] = x;
        if (depths[x] == depths[y]) depths[x]++;
      }
    }
    /// 同じ木に属するか
    bool same(int x, int y) {
      return root(x) == root(y);
    }
  private:
    int *parents;
    int *depths;
};

/// 最小全域木 O(|E|log|V|)
/// <param name="g">隣接行列のグラフ　辺がなければある程度大きな値</param>
/// <returns>重みの総和の最小値</returns>
int prim(vector<vector<int>>& g) {
  int V = g.size();
  int *mincost = new int[V];
  bool *done = new bool[V];
  fill(mincost, mincost + V, INF);
  fill(done, done + V, false);
  mincost[0] = 0;
  int res = 0;
  while (true) {
    int v = -1;
    for (int u = 0; u < V; u++)
      if (!done[u] && (v == -1 || mincost[u] < mincost[v])) v = u;
    if (v == -1) break;
    done[v] = true;
    res += mincost[v];
    for (int u = 0; u < V; u++)
      mincost[u] = min(mincost[u], g[v][u]);
  }
  return res;
}

int main() {
  int n = IN;
  auto g = vector<vector<int>>(n, vector<int>(n));
  rep(i, n) rep(j, n) {
    int t = IN;
    g[i][j] = t == -1 ? INF : t;
  }
  OUT(prim(g));
}

