const int MAX_N=101;
struct edge{
    int src,dst,cost;
    edge(int src,int dst,int cost):
    src(src),dst(dst),cost(cost){}
    };
bool operator < (const edge &m,const edge &f){
    return m.cost!=f.cost?m.cost<f.cost:
    m.src!=f.src?m.src<f.src:m.dst<f.dst;
}
struct UnionFind{
    int par[MAX_N],rank[MAX_N]; 
    void init(int n){
        for (int i=0;i<n;i++){par[i]=i;rank[i]=0;}
    } 
    int find(int x){
        if (x==par[x]) return (x);
        return (par[x]=find(par[x]));
    }
    void unite(int x, int y){
        x=find(x);y=find(y);       
        if(x==y) return;
        if(rank[x]<rank[y]){par[x]=y;}
        else{par[y]=x;if(rank[x]==rank[y]) rank[x]++;}
    } 
    bool same(int x, int y){return (find(x) == find(y));} 
};
vector<edge> ve;
int n;
int kruskal(){
    sort(ve.begin(),ve.end());
    UnionFind uf;
    uf.init(n);
    int res=0;
    rep(i,ve.size()){
        edge m=ve[i];
        if(!uf.same(m.src,m.dst)){
            uf.unite(m.src,m.dst);
            res +=m.cost;
        }
    }
    return res;
}
