int MST(priority_queue<Edge>,int);
bool check(int[][100],int,int,int);//src,dstで結ばれる線を追加した時、グラフは閉路かどうかのチェック関数

int main(int argc,char* argv[]){
  int n,val;
  priority_queue<Edge> que;

  cin>>n;
  for(int i=1;i<=n;i++){
    for(int j=1;j<=n;j++){
      cin>>val;
