}

int MST(priority_queue<Edge> que,int n){
  int ans=0;
  int flag[100][100];
  set<int> s;
  memset(flag,0,sizeof(flag[100][100]));

  while((int)s.size()!=n){
    Edge tmp(0,0,0);
    int ftmp[100][100];
    tmp=que.top();que.pop();
    memcpy(ftmp,flag,sizeof(flag));

    if(tmp.weight!=-1 && flag[tmp.src][tmp.dst]!=1){
      if(check(ftmp,tmp.src,tmp.dst,n)){
	flag[tmp.src][tmp.dst]=1;flag[tmp.dst][tmp.src]=1;
	s.insert(tmp.src);s.insert(tmp.dst);
	ans+=tmp.weight;
      }
    }
  }
  return ans;
}

bool check(int flag[][100],int src,int dst,int n){
  flag[src][dst]=1;
  queue<int> que;
  que.push(src);
  while(!que.empty()){
    int tmp=que.front();que.pop();

    for(int i=1;i<=n;i++){
      if(flag[tmp][i]==1){
	flag[tmp][i]=0;flag[i][tmp]=0;
	que.push(i);
      }
    }
    if(que.front()==src)
      return false;
  }

  return true;
}

