  vector<ll> bit;

  Fenwick() : N(0) {}
  Fenwick(int n) : N(n), bit(N + 1, 0) {}

  void add(int i, ll x)
  {
    ++i; //0-indexedを避けるために加算
    while (i <= N)
    {
      bit[i] += x;
      i += (i & -i);
    }
  }

  ll sum(int i)
  {
    ll res = 0;
    while (i > 0)
    {
      res += bit[i];
      i -= (i & -i);
    }
    return res;
  }

  ll range(int i, int j)
  {
    return sum(j) - sum(i);
  }

  ll get(int i)
  {
    return sum(i) - sum(i - 1);
  }
};
