class Side {
public:
	int r, l;
	int w;
	Side(int right, int left, int weight) {
		r = right;
		l = left;
		w = weight;
	};
	bool operator>=(Side s) {
		return w >= s.w;
	}
	bool operator<(Side s) {
		return w < s.w;
	}
};

class Node {
public:
	int p; /// parent
	int d; /// depth
	Node() {
		p = -1;
		d = 1;
	}
};

int Find(std::vector<Node> n, int i) {
	int a = i;
	while (1) {
		if (n[a].p == -1) return a;
		a = n[a].p;
	}
}

bool Union(std::vector<Node> &n, int i, int j) {
	int a = Find(n, i);
	int b = Find(n, j);
	if (a == b) return false;
	if (n[a].d <= n[b].d) {
		n[b].p = a;
		n[a].d = n[b].d + 1;
	}
	else {
		n[a].p = b;
		n[b].d = n[a].d + 1;
	}
	return true;
}

int main() {
	int n;
	std::cin >> n;
	std::vector<Side> side;
	std::vector<Node> node(n);

	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			int a;
			std::cin >> a;
			if (a != -1) {
				side.push_back(Side(i, j, a));
			}
		}
	}

	std::sort(side.begin(), side.end());
	int m = side.size();
	int cnt = 0;
	int weight = 0;


	for (int i = 0; i < m; i++) {
		if (Union(node, side[i].r, side[i].l)) {
			cnt++;
			weight += side[i].w;
		}
		if (cnt == n - 1) break;
	}

	std::cout << weight << std::endl;
}

