typedef pair<int, int> P;
const int M = 1000000007;

int prim_cost(vector<vector<P>> edge) {
    int n = edge.size();
    vector<int> vis(n, 0);
    int c = 0;
    priority_queue<P, vector<P>, greater<P>> q;
    q.push(P(0, 0));
    while (!q.empty()) {
        P p = q.top();
        q.pop();
        if (vis[p.second]) continue;
        vis[p.second] = 1;
        c += p.first;
        for (auto& e : edge[p.second]) {
            if (!vis[e.second]) {
                q.push(P(e.first, e.second));
            }
        }
    }
    return c;
}


