    int n;
    cin >> n;

    for(int i = 0;i < n;++i){
        for(int j = 0;j < n;++j){
            int edge;
            cin >> edge;
            gMatrix[i][j] = (edge == -1) ? INFTY : edge;
        }
    }

    cout << prim(n) << endl;
    return 0;
}

