      if((*l).src<(*l).dst && (*l).weight>0)
	que.push(*l);
    }
  }

  //PrintPriority_queue(que);
  int sum=0;
  Edges select;

  while((int)select.size()<n && !que.empty()){
    Edge tmp=que.top();que.pop();

    if(!uf.findset(tmp.src,tmp.dst)){
      uf.unionset(tmp.src,tmp.dst);
      select.push_back(tmp);
      sum+=tmp.weight;
    }
  }

  return pair<int,Edges>(sum,select);
}


