int minSpanningTreeRecursive(int16_t currentV, const bool visited[], string path)
{
  assert(0 <= currentV && currentV < gNumOfVertices);

  bool updatedVisited[gNumOfVertices];

  for (int i = 0; i < gNumOfVertices; i++)
    updatedVisited[i] = visited[i];

  updatedVisited[currentV] = true;

  // This function ensures all of elements are unvisited
  vector<int16_t> nextVs = getConnectedVs(currentV, updatedVisited);

  if (nextVs.size() == 0)
    return 0;

  //string minPath;
  int minV = -1;
  int minScore = INT_MAX;
  string currentPath = to_string(currentV);

  if (path.size())
    currentPath = path + " > " + currentPath;

  for (int i = 0; i < nextVs.size(); i++)
  {
    const int16_t nextV = nextVs[i];
    const int score = gWeightOfVij[currentV][nextV] + minSpanningTreeRecursive(nextV, updatedVisited, currentPath);

    if (minScore > score)
    {
      minScore = score;
      minV = nextV;
    }

  }

  {
    string minPath = "[" + to_string(currentV) + "] > " + to_string(minV);

    if (path.size())
      minPath = path + " > " + minPath;

    DPRINTF("score %d (currentV %d)\n", minScore, currentV);
    DPRINTF("  %s\n", minPath.c_str());
  }

  return minScore;
}


