using namespace std;

class union_find {
  vector<int> uf;

public:
  union_find(int sz)
  {
    uf = vector<int>(sz);
    for (int i = 0; i < sz; i++)
      uf[i] = i;
  }

  int root(int i)
  {
    if (uf[i] == i) return i;
    return uf[i] = root(uf[i]);
  }

  void unite(int i, int j)
  {
    int ri = root(i);
    int rj = root(j);
    if (ri != rj)
      uf[rj] = ri;
  }

  bool same(int i, int j)
  {
    return root(i) == root(j);
  }
};

typedef pair<int, int> edge;
typedef pair<edge, int> V;
priority_queue<V, vector<V>, function<bool(V, V)>> que(
  [](V a, V b) { return a.second >= b.second; }
);

#define make_V(i, j, w) make_pair(make_pair((i), (j)), (w))

int solve(int n)
{
  union_find uf(n);

  int ans = 0;
  while (!que.empty()){
    int i, j, w;
    V v = que.top(); que.pop();
    i = v.first.first, j = v.first.second;
    w = v.second;

    if (uf.same(i, j)) continue;
    uf.unite(i, j);
    ans += w;

    // printf("(%d, %d) %d\n", v.first.first, v.first.second, v.second);
  }

  return ans;
}

