struct UnionFind{
    vector<int> par;

    UnionFind(int n)
        :par(n)
    {
        for(int i=0;i<n;i++){
            par[i]=i;
        }
    }

    void unite(int x,int y){
        int rx=root(x),ry=root(y);
        if(rx==ry)return;
        else{
            par[rx]=ry;
            return;
        }
    }

