void kruskal(Edges es){
  priority_queue<edge> que;
  int cost = 0;
  UnionFind uf;
  for(int i = 0;i < (int)es.size();i++)
	que.push(es[i]);

  while(!que.empty()){
	edge e = que.top();que.pop();

	if(!uf.findset(e.src,e.dst)){
	  uf.unionset(e.src,e.dst);
	  cost += e.weight;
	}
  }

  printf("%d\n",cost);
}


int UnionFind::root(int x){
  return (par[x] == x) ? x : root(par[x]);
}

bool UnionFind::findset(int x,int y){
  return root(x) == root(y);
}

void UnionFind::unionset(int x,int y){
  x = root(x);
  y = root(y);

  if(x == y)
	return;

  if(rank[y] < rank[x])
	swap(x,y);
  par[y] = x;
  rank[x] += rank[y];
}

