static const int GRAY = 1;
static const int BLACK = 2;

int n, M[MAX][MAX]; //M:隣接行列

int prim() {
    int u, minv;
    int distance[MAX], parent[MAX], color[MAX];

    for(int i = 0; i < n; i++) {
        distance[i] = INF;
        parent[i] = -1;
        color[i] = WHITE;
    }

    distance[0] = 0;

    while (true) {
        minv = INF;
        u = -1;
        for(int i = 0; i < n; i++) {
            if (minv > distance[i] && color[i] != BLACK) {
                u = i;
                minv = distance[i];
            }
        }

        if (u == -1)
            break;

        color[u] = BLACK;
        for(int v = 0; v < n; v++) {
            if (color[v] != BLACK && M[u][v] != INF) {
