struct Edge{
    int from, to, cost;
    Edge(int f, int t, int c){
        from = f;
        to = t;
        cost = c; 
    }
};
bool operator< (const Edge& e1, const Edge& e2){
    return e1.cost < e2.cost;
}
bool operator> (const Edge& e1, const Edge& e2){
    return e1.cost > e2.cost;
}
int makeMST(vector<vector<int>> &G, vector<vector<int>> &H){
    int N = G.size();
    int res = 0;
    int v = 0;
    priority_queue<Edge, vector<Edge>, greater<Edge> > pq;
    vector<int> visited(N, 0);
    visited[0] = 1;
    for(int i=0; i<N; i++) if(G[v][i]!=-1) pq.push(Edge(0, i, G[v][i]));
    int numv = 1;
    while(pq.size() and numv!=N){
        Edge e = pq.top(); pq.pop();
        if(visited[e.to]) continue;
        res += e.cost;
        visited[e.to] = 1;
        H[e.from][e.to] = e.cost;
        H[e.to][e.from] = e.cost;
        for(int i=0; i<N;i++){
            if(G[e.to][i]!=-1 and !visited[i]) pq.push(Edge(e.to, i, G[e.to][i]));
        }
        numv++;
    }
    return res;
}

