using namespace std;

class DisjointSet {
private:
	vector<int> P;		//添え字の番号の頂点の親
	vector< unordered_set<int> > Set;		//添え字の番号の頂点に子として繋がっている頂点の集合
public:
	DisjointSet(int n);
	void unite(int x, int y);
	bool same(int x, int y);
};

DisjointSet::DisjointSet(int n) : P(n), Set(n) {
	for (int i = 0; i<n; ++i) {
		P[i] = i;
		Set[i].insert(i);
	}
}

void DisjointSet::unite(int x, int y) {
	if (P[x] == P[y])
		return;
	int big, small;
	if (Set[P[x]].size() >= Set[P[y]].size()) {
		big = P[x];
		small = P[y];
	}
	else {
		big = P[y];
		small = P[x];
	}
	for (auto i = Set[small].begin(); i != Set[small].end(); ++i) {
		P[*i] = big;
		Set[big].insert(*i);
	}
}

bool DisjointSet::same(int x, int y) {
	return P[x] == P[y];
}

class MSTree : public DisjointSet {
private:
	const int vertex_n;
	vector< pair<int, int> > edge;		//firstは辺の重さ、secondは辺のID(始点・終点)
public:
	MSTree(int n) : DisjointSet(n), vertex_n(n), edge(n*n) {
		for (int i = 0; i < n*n; i++) {
			edge[i].first = -1;
			edge[i].second = i;
		}
	}
	int& GetEdgeWeight(int i, int j) { return edge[vertex_n*i + j].first; }
	int MinEdgeSum();
};

int MSTree::MinEdgeSum() {
	int sum = 0;
	sort(edge.begin(), edge.end());
	for (int i = 0; i < vertex_n*vertex_n; i++) {
		int from = edge[i].second / vertex_n, to = edge[i].second % vertex_n;
		if (edge[i].first == -1 || this->same(from, to))
			continue;
		else {
			this->unite(from, to);
			sum += edge[i].first;
		}
	}
	return sum;
}

int main() {
	int n;
	cin >> n;
	MSTree mst(n);
	for (int i = 0; i < n; i++)
		for (int j = 0; j < n; j++)
			cin >> mst.GetEdgeWeight(i, j);
	cout << mst.MinEdgeSum() << endl;
}

