template <class T>
using Priority_que = priority_queue< T, vector<T>, greater<T> >;

int N;
vector<pii> G[102];
int mcos[102];

void dijkstra(int s)
{
   Priority_que < pii > pq;
   pq.push( mkp(0, s) );
   memset( mcos, INF, sizeof(mcos) );
   mcos[s] = 0;

   while(!pq.empty()){
      const pii& tmp = pq.top();
      pq.pop();
      const int u = tmp.se;
      if( mcos[u] < tmp.fi )continue;
      for( auto& v : G[u] ){
         const int nc = v.fi + tmp.fi;
         const int nxt = v.se;
         if( chmin( mcos[nxt], nc ) ){
            pq.push( mkp(nc, nxt) );
         }
      }
   }
   return ;
}

