int prim() {
	int u, minv;
	int D[MAX], P[MAX], C[MAX];

	for (int i = 0; i < N; i++) {
		D[i] = INFTY;
		P[i] = -1;
		C[i] = WHITE;
	}

	D[0] = 0;
	while (true) {
		minv = INFTY;
		u = -1;
		for (int i = 0; i < N; i++) {
			if (minv > D[i] && C[i] != BLACK) {
				u = i;
				minv = D[i];
			}
		}
		if (u == -1) break;
		C[u] = BLACK;
		for (int v = 0; v < N; v++) {
			if (C[v] != BLACK && M[u][v] != INFTY) {
				if (D[v] > M[u][v]) {
					D[v] = M[u][v];
					P[v] = u;
					C[v] = GRAY;
				}
			}
		}
	}
	int sum = 0;
	for (int i = 0; i < N; i++) {
		if (P[i] != -1) sum += M[i][P[i]];
	}
	return sum;
}

