	vector<pair<int, pair<int, int> > > edge;

	REP(x, N) {
		REP(y, N) {
			int c;
			cin >> c;
			if ( x <= y ) { continue; }
			if ( c == -1 ) { continue; }
			edge.push_back( make_pair(c, make_pair(x,y)) );
		}
	}

	sort(edge.begin(), edge.end());

	unionf uf(N);

	int cnt = 0;
	int ret = 0;
	REP(i, edge.size() ) {

		pair<int, int> sd = edge[i].second;
		if ( ! uf.issame( sd.first, sd.second ) ) {
			cnt ++;
			ret += edge[i].first;
		}

		if ( cnt == N-1 ) { break; }
	}

	cout << ret << endl;
}

