#include <queue>

using namespace std;

int prim(vector<vector<pair<int, int> > >& G) {
	int cost = 0;
	const int N = G.size();
	vector<bool> used(G.size());
	priority_queue<pair<int, int>, vector<pair<int, int> >, greater<pair<int, int> > > pq;
	pq.push(make_pair(0, 0));
	while (!pq.empty()) {
		pair<int, int> p = pq.top(); pq.pop();
		int now = p.second;
		if (used[now]) continue;
		used[now] = true;
		cost += p.first;
		for (auto e : G[now])
			pq.push(make_pair(e.second, e.first));
	}
	return cost;
}

int main() {
	int n; cin >> n;
	vector<vector<pair<int, int> > > G(n);
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			int a; cin >> a;
			if (a != -1) G[i].push_back(make_pair(j, a));
		}
	}
	cout << prim(G) << endl;

	return 0;
}

#include<iostream>
using namespace std;

class Edge {
public:
	int v1, v2, d;
};

int n, k=0, V[100];
Edge E[5000];

void Sort() {
	for (int i = 1; i < k; i++) {
		Edge v = E[i];
		int j = i - 1;
		while (j >= 0 && E[j].d > v.d) {
			E[j + 1] = E[j];
			j--;
		}
		E[j + 1] = v;
	}
}

int Kruskal() {
	int m = 0;
	for (int i = 0; i < k; i++) {
		Edge e = E[i];
		if (V[e.v1] != V[e.v2]) {
			int v = V[e.v1], u = V[e.v2]; m += e.d;
			for (int j = 0; j < n; j++) {
				if (V[j] == u) V[j] = v;
			}
		}
	}
	return m;
}

int main() {
	int g;
	cin >> n;
	for (int i = 0; i < n; i++) {
		V[i] = i;
		for (int j = 0; j < n; j++) {
			cin >> g;
			if (i < j && g > -1) {
				E[k].v1 = i; E[k].v2 = j; E[k].d = g; k++;
			}
		}
	}

	Sort();

	cout << Kruskal() << endl;
}

