struct UnionFind {
    // ?????????????´???°??????????????§????´?
    UnionFind(size_t n) : uni(n, -1), n_set(n), cost_sum(n, 0) {}

    size_t size() const { return uni.size(); }

    // ??????????????°
    size_t set_count() const { return n_set; }

    int root(int x)
    {
        if(uni[x] < 0) return x;
        return uni[x] = root(uni[x]);
    }

    void unite(int x, int y, int cost)
    {
        int rx = root(x);
        int ry = root(y);
        if(rx != ry) {
            // ????´???°?????§?????????????????¨??????
            if(uni[rx] > uni[ry])
                swap(rx,ry);
            uni[rx] += uni[ry];
            uni[ry] = rx;
            --n_set;
            cost_sum[rx] += cost + cost_sum[ry];
        }
        else {
            assert(false);
        }
    }

    bool same(int x, int y)
    {
        return root(x) == root(y);
    }

    vector<int> uni;
    size_t n_set;
    vector<int> cost_sum;
};

int N;

void solve()
{
    vector<tuple<int,int,int>> edges; // cost,u,v

    REP(u, N) {
        vector<int> row(N);
        REP(v, N) {
            RD(row[v]);
        }
        FOR(v, u+1, N) {
            int cost = row[v];
            if(cost == -1) continue;
            edges.emplace_back(cost, u, v);
        }
    }
    ALL(sort, edges);
#ifdef DEBUG
    DBG(edges);
#endif

    UnionFind uf(N);

    for(const auto& e : edges) {
        int cost,u,v; tie(cost,u,v) = e;
        if(uf.same(u,v)) continue;
        uf.unite(u,v,cost);
#ifdef DEBUG
        DPRINTLN("unite:", u, v, cost);
        DBG(uf.uni);
        DBG(uf.cost_sum);
#endif
    }
#ifdef DEBUG
    DBG(uf.uni);
    DBG(uf.cost_sum);
#endif

    // ??£?????¨???????????????????????§???
    int ans = uf.cost_sum[uf.root(0)];
    PRINTLN(ans);
}

signed main(signed /*argc*/, char** /*argv*/)
{
    RD(N);

    solve();

    EXIT();
}

