int n, M[MAX][MAX];

int prim() {
  int u, minv;
  // d: TとT-Vをつなぐ重みが最小の辺の重み
  // p: p[v]に頂点vの親
  int d[MAX], p[MAX], color[MAX];

  for (int i = 0; i < n; i++) {
    d[i] = INF;
    p[i] = -1;
    color[i] = WHITE;
  }

