int main () {
  // first 权重，second 顶点 id
  priority_queue<pair<int, int>, vector<pair<int, int> >, greater<pair<int, int> > > V[N];
  int n, a, T[N], cost = 0, cnt = 0;

  cin >> n;

  // 输入为邻接矩阵
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      cin >> a;

      if (a >= 0) {
        V[i].push(make_pair(a, j));
      }
    }
  }

  for (int i = 0; i < N; i++)
    T[i] = 0;

  T[0] = 1;

  while (cnt < n - 1) {
    int minCost = (1 << 21);
    int minI;

    // cout << "cnt = " << cnt << endl;

    for (int i = 0; i < n; i++) {
      if (T[i]) {
        // cout << "i = " << i << endl;
        while (V[i].size() && T[V[i].top().second])
          V[i].pop();

        if (V[i].size() && V[i].top().first < minCost) {
          minCost = V[i].top().first;
          minI = i;
        }
      }
    }

    // cout << minI << " " << V[minI].top().first << " " << V[minI].top().second << endl;

    cost += V[minI].top().first;
