// pll : (cost, dst)
ll MST(const vector<vector<pll>>& G) {
	const ll INF = 1LL << 60;
	int V = G.size();
	vector<ll> mincost(V, INF);
	vector<ll> used(V, false);

	priority_queue<pll, vector<pll>, greater<pll>> pq;
	mincost[0] = 0;
	pq.push(pll(0, 0));
	ll MSTcost = 0;

	while (!pq.empty()) {
		pll p = pq.top(); pq.pop();
		int v = p.second;
		if (used[v])
			continue;
		used[v] = true;
		MSTcost += mincost[v];
		for (int i = 0; i < G[v].size(); i++) {
			pll e = G[v][i];
			if (mincost[e.second] > e.first) {
				mincost[e.second] = e.first;
				pq.push(e);
			}
		}
	}

	return MSTcost;
}



class RandomSet {
	struct Xor128 {
		unsigned x, y, z, w;
		Xor128(int _w) { x = 123456789; y = 362436069; z = 521288629; w = _w; }
		unsigned nextUInt() {
			unsigned t = (x ^ (x << 11));
			x = y; y = z; z = w;
			return (w = (w ^ (w >> 19)) ^ (t ^ (t >> 8)));
		}
	} rnd;
	unordered_set<int> st;
	vector<unordered_set<int>::iterator> its;
public:
	RandomSet(unsigned seed = 88675123) : rnd(seed) {}
	auto begin() { return st.begin(); }
	auto end() { return st.end(); }
	auto empty() { return st.empty(); }
	auto size() { return st.size(); }
	auto insert(int key) {
		auto ret = st.insert(key);
		if (ret.second == true)
			its.push_back(ret.first);
		return ret;
	}
	auto random() {
		unsigned idx = rnd.nextUInt() % size();
		return *its[idx];
	}
	auto pop_random() {
		unsigned idx = rnd.nextUInt() % size();
		auto key = *its[idx];
		swap(its[idx], its.back());
		st.erase(key);
		its.pop_back();
		return key;
	}
};



// WTy : weight type
template<typename WTy> class RandomGraphGenerator {

	struct SXor128 {
		unsigned x, y, z, w;
		SXor128(unsigned _w) { x = 123456789; y = 362436069; z = 521288629; w = _w; }
		unsigned nextUInt() {
			unsigned t = (x ^ (x << 11));
			x = y; y = z; z = w;
			return (w = (w ^ (w >> 19)) ^ (t ^ (t >> 8)));
		}
	} rnd;

	int V, E;
	WTy W;
	unsigned seed;

public:

	RandomGraphGenerator(int V, int E, WTy W = WTy(1), int seed = 88675123) : V(V), E(E), W(W), seed(seed), rnd(seed) {}

	vector<tuple<int, int, WTy>> generate() {

		// e = (u, v) を (u << 32) + v にコンバートして管理
		unordered_set<ll> edges;
		edges.reserve(E);

		// --- 全域木の生成 ---
		// T = {}, G = {0, 1, ..., |V| - 1}
		// G からランダムに始点 s を pop して T に追加
		// G が空になるまで:
		//	T からランダムに 1 点 u を選択
		//	G からランダムに 1 点 v を pop
		//	辺 e = (u, v) を張る
		//	v を T に追加
		RandomSet T(rnd.nextUInt()), G(rnd.nextUInt());
		for (int i = 0; i < V; i++)
			G.insert(i);
		T.insert(G.pop_random());
		for (int i = 0; i < V - 1; i++) {
			ll u = T.random();
			ll v = G.pop_random();
			edges.insert((u << 32) + v);
			T.insert((int)v);
		}

		// 辺が E 本になるまでランダムな 2 点に辺を張る
		int R = E - (int)edges.size();
		for (int i = 0; i < R; i++) {
			//if (edges.size() % 100000 == 0) {
			//	cerr << edges.size() << endl;
			//}
			ll u, v;
			do {
				u = T.random();
				v = T.random();
				while (u == v) {
					v = T.random();
				}
				if (u > v)
					swap(u, v);
			} while (edges.find((u << 32) + v) != edges.end()); // 多重辺を避ける
			edges.emplace((u << 32) + v);
		}

		vector<tuple<int, int, WTy>> weighted_edges;
		weighted_edges.reserve(E);

		for (const auto& e : edges)
			weighted_edges.emplace_back(int(e >> 32), int(e & 0xffffffff), WTy(rnd.nextUInt() % W + 1));

		return weighted_edges;
	}
};



