  V = n;
  REP(i, n) {
    REP(j, n) {
      if (a[i][j] == -1) {
        cost[i][j] = INF;
      } else {
        cost[i][j] = a[i][j];
      }
    }
  }
  std::cout << prim() << std::endl;
}

int main() {
  long long n;
  scanf("%lld", &n);
  vector<vector<long long>> a(n, vector<ll>(n));
  REP(i, n) {
    REP(j, n) {
      scanf("%lld", &a[i][j]);
    }
  }
  solve(n, std::move(a));
  return 0;
}

