class Edge{
public:
	ll to,weight;
	bool use{true};
	Edge(ll t,ll w):to(t),weight(w){}
};

class Edge2{
public:
	ll from,to,weight;
	Edge2()=default;
	Edge2(ll f,ll t,ll w):from(f),to(t),weight(w){}
};

class ConnectNodeInfo{
	vector<vector<Edge>> graph;
public:
	ConnectNodeInfo(int node_num){
		graph.resize(node_num);
	}
	void AddNonDirectionalConnection(ll u,ll v,ll w){
		graph[u].emplace_back(v,w);
		graph[v].emplace_back(u,w);
	}
	void AddDirectionalConnection(ll u,ll v,ll w){
		graph[u].emplace_back(v,w);
	}
	vector<Edge>& operator[](ll index){
		return graph[index];
	}
	size_t size(){return graph.size();}
};

class SearchPath{
	set<ll> visit;

	bool CanReachImpl(int start,int end,ConnectNodeInfo& connect){
		bool reach=false;
		if(start==end) return true;

		for(int i=0,ei=connect[start].size();i<ei;i++){
			if(!connect[start][i].use) continue;
			auto res = visit.emplace(connect[start][i].to);
			if(!res.second) continue;
			reach |= CanReachImpl(connect[start][i].to,end,connect);
		}
		return reach;
	}
public:
	bool CanReach(int start,int end,ConnectNodeInfo& connect){
		visit.clear();
		visit.emplace(start);
		return CanReachImpl(start,end,connect);
	}
};

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);

	int N=in();
	vector<vector<int>> C(N,vector<int>(N));
	ConnectNodeInfo connect(N);
	vector<Edge2> edge;
	REP(i,N){
		REP(j,N){
			C[i][j]=in();
		}
	}
	REP(i,N){
		for(int j=i;j<N;j++){
			int v=C[i][j];
			if(v!=-1){
				connect.AddNonDirectionalConnection(i,j,v);
				edge.emplace_back(i,j,v);
			}
		}
	}
	sort(ALL(edge),[](Edge2& l,Edge2& r){return l.weight>r.weight;});
	SearchPath sp;
	int M=edge.size();
	ll sum=0;
	REP(i,M){
		auto& e=edge[i];
		for(auto& x:connect[e.from]){
			if(x.to==e.to) x.use=false;
		}
		for(auto& x:connect[e.to]){
			if(x.to==e.from) x.use=false;
		}
		if(!sp.CanReach(e.from,e.to,connect)){
			for(auto& x:connect[e.from]){
				if(x.to==e.to) x.use=true;
			}
			for(auto& x:connect[e.to]){
				if(x.to==e.from) x.use=true;
			}
			sum+=e.weight;
		}
	}

	out(sum);
	return 0;
}

