struct UnionFind {
	int V;
	vector<int>ne;
	void init() { for (int i = 0;i<V;i++)ne.push_back(i); };

	int root(int x) {
		if (ne[x] == x)return x;
		return ne[x] = root(ne[x]);
	}
	bool same(int x, int y) { return root(x) == root(y); }
	void unite(int x, int y) {
		if (same(x, y))return;
		if (x>y)swap(x, y);
		ne[ne[y]] = ne[x];
		return;
	}
};

struct Edge{
	int fr,to,val;
	bool operator < (Edge x){
		return (val<x.val);
	}
};

vector<Edge>e;
int n;

int MST() {//最小全域木の重みの総和
	int ret = 0;
	UnionFind uf;
	uf.V = n;
	uf.init();
	sort(e.begin(), e.end());
	for (int i = 0;i<e.size();i++) {
		if (uf.same(e[i].fr, e[i].to))continue;
		ret += e[i].val;
		uf.unite(e[i].fr, e[i].to);
	}
	return ret;
}


