#include <iostream>
#include <vector>
#include <queue>
using namespace std;
typedef vector <int> vi;
typedef vector <vi> vvi;

class blanch{
	public:
		int weight;
		int from;
		int to;
		blanch():
			weight(0),from(0),to(0){};
		blanch(int newweight, int newfrom, int newto):
			weight(newweight),from(newfrom),to(newto){};
};
typedef vector <blanch> vb;

bool operator<( const blanch &blanch1, const blanch &blanch2){
	return (blanch1.weight > blanch2.weight);
	}

bool operator>( const blanch &blanch1, const blanch &blanch2){
	return (blanch1.weight < blanch2.weight);
	}

int make_graph(vvi &graph, vi &stamp){
	int n=graph.size();
	for (int j=0; j<n; j++){
		for (int i=0; i<n; i++){
			cin>>graph[i][j];
		}
		stamp[j] = 0;
	}
	return 0;
}

int Minimum_Spanning_Tree(vvi &graph, vi &stamp){

	priority_queue<blanch, vb, less<vb::value_type> > pq;
	int n = graph.size(), p1=0, total=0;
	stamp[p1] = 1;

	while (p1!=-1){
		for (int p2=0; p2<n; p2++){
			int *tmp = &graph[p1][p2];
			if (*tmp!=-1 && stamp[p2]==0){
				pq.push(blanch(*tmp, p1, p2));
			}
		}
		p1 = -1;
		while (! pq.empty()){
			blanch tmp = pq.top();
			if (stamp[tmp.from]==1 && stamp[tmp.to]==0){
				p1 = tmp.to;
				stamp[p1] = 1;
				total += tmp.weight;
				pq.pop();
				break;
			}
			pq.pop();
		}
	}
	return total;
}

int main(void){

	int n;
	cin>>n;
	vvi G(n, vi(n));
	vi stamp(n);

	make_graph(G, stamp);

	cout<<Minimum_Spanning_Tree(G, stamp)<<endl;

	return 0;
}

