// pii : (cost, dst)
int MST(const vector<vector<pii>>& G) {
	int cost = 0;

	int n = G.size();
	vector<bool> visited(n, false);
	// 始点 0 を訪問
	visited[0] = true;
	// 始点 0 から生える辺を priority_queue に追加
	priority_queue<pii, vector<pii>, greater<pii>> pq;
	for (const auto& e : G[0])
		pq.push(e);

	// n - 1 回辺を追加すれば MST ができる
	for (int i = 0; i < n - 1; i++) {
		while (!pq.empty()) {
			int d, v;
			tie(d, v) = pq.top(); pq.pop();
			// 訪問済みなら continue
			if (visited[v])
				continue;
			// 辺追加
			visited[v] = true;
			cost += d;
			for (const auto& e : G[v])
				pq.push(e);
			break;
		}
	}

	return cost;
}

int main() {

	cin.tie(0);
	ios::sync_with_stdio(false);

	int n;
	cin >> n;
	vector<vector<pii>> G(n);
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			int d;
			cin >> d;
			if (d == -1)
				continue;
			G[i].emplace_back(d, j);
		}
	}

	cout << MST(G) << endl;

	return 0;
}

