using namespace std;

vector<int> djset, szset;
vector<pair<int, pair<int, int>>> G;

int root(int x)
{
    int v = djset[x];
    while (v != djset[v]) v = djset[v];
    djset[x] = v;
    return v;
}

int main(void)
{
    int N;
    cin >> N;
    G.resize(N * N);
    int count = 0;
    int temp;
    for (int i = 0; i < N; i++)
    {
        for (int j = 0; j < N; j++)
        {
            cin >> temp;
            if (i == j || temp == -1) continue;
            G[count++] = make_pair(temp, make_pair(i, j));
        }
    }
    djset.resize(count);
    szset.resize(count, 1);
    G.erase(G.begin() + count, G.end());
    sort(G.begin(), G.end());
    for (int i = 0; i < count; i++) djset[i] = i;
    int v[2], r[2];
    int ans = 0;
    for(auto i : G)
    {
        v[0] = i.second.first;
        v[1] = i.second.second;
        for (int i = 0; i < 2; i++) r[i] = root(v[i]);
        if (r[0] == r[1]) continue;
        if (szset[r[1]] > szset[r[0]]) swap(r[0], r[1]);
        djset[r[1]] = r[0];
        szset[r[0]] += szset[r[1]];
        szset[r[1]] = 0;
        ans += i.first;
    }
    cout << ans << endl;
    return 0;
}

