#include <stdio.h>

typedef struct{
    int d,x,y;
}Edge;

void addHeap(int n,Edge a[]){
    int dd,xx,yy;
    while(n>1){
        if(a[n/2-1].d>a[n-1].d){
            dd=a[n-1].d;xx=a[n-1].x;yy=a[n-1].y;
            a[n-1].d=a[n/2-1].d;a[n-1].x=a[n/2-1].x;a[n-1].y=a[n/2-1].y;
            a[n/2-1].d=dd;a[n/2-1].x=xx;a[n/2-1].y=yy;
        }else{break;}
        n/=2;
    }
}

void heap(int i,int n,Edge a[]){
    int min,mnum,dd,xx,yy;
    if(i*2>n){
        return;
    }
    min = a[i-1].d;mnum=i;
    if(min>a[i*2-1].d){
        min=a[i*2-1].d;mnum=i*2;
    }
    if(i*2+1<=n&&min>a[i*2].d){
        min=a[i*2].d;mnum=i*2+1;
    }
    if(mnum!=i){
        dd=a[i-1].d;xx=a[i-1].x;yy=a[i-1].y;
        a[i-1].d=a[mnum-1].d;a[i-1].x=a[mnum-1].x;a[i-1].y=a[mnum-1].y;
        a[mnum-1].d=dd;a[mnum-1].x=xx;a[mnum-1].y=yy;
        heap(mnum,n,a);
    }
}

Edge get(int n,Edge a[]){
    int i;
    Edge k;
    k.d=a[0].d;k.x=a[0].x;k.y=a[0].y;
    a[0].d=a[n-1].d;a[0].x=a[n-1].x;a[0].y=a[n-1].y;n--;
    heap(1,n,a);
    return k;
}

void chenge(int a,int b,int f[],int n){
    int i;
    for(i=0;i<n;i++){
        if(f[i]==a){
            f[i]=b;
        }
    }
}

