int generic(int n){
  int i, sum = 0;
  for (i = 0; i < n - 1; i++){
	  sum += minSearch(n, i);
  }
  return sum;
}

int minSearch(int n, int c){
  int i, j, minr, min;
  min = INFTY;
  for(i = 0; i <= c; i++){
	if(p[i] != 0){
		for(j = i + 1; j < n; j++){
			if (M[i][j] < min) {
			  min = M[i][j];
			  minr = j;
			}
		}
	}
  }

  p[minr] = 1;
  M[min][minr] = INFTY;
  M[minr][min] = INFTY;
  return min;
}

