/*qsort用*/
int cmp(const void *p,const void *q){
	return ((edge*)p)->cost - ((edge*)q)->cost;
}


int find(int u,int b[]){
	if(b[u]==u){
		return u;
	}else {
		return b[u]=find(b[u],b);
	}
}

void merge(int u,int v,int b[]){
	if(b[u] < b[v]){
		if(v!=b[v])
			merge(u,b[b[v]],b);
		b[v]=b[u];
	}
	else {
		if(u!=b[u])
			merge(v,b[b[u]],b);
		b[u]=b[v];
	}
	return;
}



