int prim(int n, int a[MAX_N][MAX_N])
{
    int i, v, cost[MAX_N], used[MAX_N], res = 0;
    for(i=0; i<n; i++){
        cost[i] = INF;
        used[i] = 0;
    }

    cost[0] = 0;
    while(1){
        v = -1;
        for(i=0; i<n; i++){
            if(!used[i] && (v == -1 || cost[i] < cost[v])){
                v = i;
            }
        }
        if(v == -1){
            break;
        }
        used[v] = 1;
        res += cost[v];
        for(i=0; i<n; i++){
            if(a[v][i] == -1){
                continue;
            }
            cost[i] = min(cost[i], a[v][i]);
        }
    }
    return res;
}

