/* プリムのアルゴリズムを用いて、重み付きグラフGの最小全域木の各辺の重みを計算する関数
   引数　r　始点　n 頂点数 　戻り値　各辺の重みの和 */
int prim(int r, int n)
{
  int i, j, u, res = 0, mincost;

  /* ノードiの色、コスト等を記録する配列を初期化　*/
  for( i = 0; i<n; i++ )
    {
      color[i] = WHITE;
      pi[i]    = NIL;
      d[i]     = INT_MAX;
    }
  d[r] = 0;

  while( 1 )
    {
      mincost = INT_MAX;
      for( i = 0; i<n; i++ )
	{
	  if( color[i] != BLACK && d[i] < mincost )
	    {
	      mincost = d[i];
	      u = i;
	    }
	}

      /*　最小全域木を構築し終わったらループを抜ける　*/
      if( mincost == INT_MAX )
	break;

      color[u] = BLACK;      /* ノードuをその時点での最小全域木に含める　*/

      /*　ノードuに隣接し、その時点での最小全域木に含まれないノードの内、コストが最小のものを求める　*/
      for( i = 0; i<n; i++ )
	{
	  if( color[i] != BLACK && G[i][u] != NIL )
	    {
	      if( d[i] > G[i][u] )
		{
		  pi[i] = u;
		  d[i]  = G[i][u];
		}
	    }
	}
    }

  for( i = 0; i<n; i++ )
    res += d[i];

  return res;
}

