#include <stdio.h>
#include <stdlib.h>
#define INF (1<<28)

int mst(int g[101][101], int n) {
  int i;
  int res, id, mini;
  int cost[101], vis[101];
  for(i = 0; i < n; ++i) {
    cost[i] = INF;
    vis[i] = 0;
  }
  cost[0] = 0;
  res = 0;
  while(1) {
    id = -1;
    mini = INF;
    for(i = 0; i < n; ++i) {
      if(vis[i]) continue;
      if(cost[i] < mini) {
        id = i;
        mini = cost[i];
      }
    }
    if(id == -1) break;
    vis[id] = 1;
    res += cost[id];

    for(i = 0; i < n; ++i) {
      if(vis[i]) continue;
      if(g[id][i] < cost[i]) {
        cost[i] = g[id][i];
      }
    }
  }
  return res;
}

