//============================================================================
#define pred(x) ((x)-1)
#define succ(x) ((x)+1)
#define True    1
#define False   0
typedef unsigned short word;
typedef unsigned char  byte;
//============================================================================
#define MAX_BUFFER  2048
#define MAX_N       100
//============================================================================
typedef struct{
    byte row,col;
    byte val;
    byte pal;
    byte res;
}TNode;
//============================================================================
TNode Node[MAX_BUFFER];
short NodePtr;
byte  NodeStack[MAX_N];
short StackPtr;
//============================================================================
void prnnode(TNode *node)
{
    printf("row=%d, col=%d, val=%d, pal=%d", node->row, node->col, node->val, node->pal);
    printf("\n");
}
//----------------------------------------------------------------------------
//----------------------------------------------------------------------------
//----------------------------------------------------------------------------
//----------------------------------------------------------------------------
//----------------------------------------------------------------------------
//----------------------------------------------------------------------------
short nodepal(short pal)
{
    short i;

    for (i=0; i<StackPtr; i++)
    if (Node[NodeStack[i]].row==pal || Node[NodeStack[i]].col==pal)
        return Node[NodeStack[i]].pal;
    return pal;
}
//----------------------------------------------------------------------------
void setnode(TNode *node, byte row, byte col, byte val)
{
    node->row=row;
    node->col=col;
    node->val=val;
    if (row<col)
        node->pal=row;
    else
        node->pal=col;
    //node->pal=nodepal(node->pal, NodePtr);
}
//============================================================================
short sort(TNode *ary, int n)
{
    short i,j,k,l, cnt; TNode chg;

    for (k=cnt=0, l=n; k<n-1; k++, l--)
    for (i=0,j=1; j<l; i++, j++){
        if (ary[j].val<ary[i].val)
            chg=ary[i], ary[i]=ary[j], ary[j]=chg, cnt++;
	}
    return cnt;
}
//----------------------------------------------------------------------------
//----------------------------------------------------------------------------
void pushnode(byte n)
{
    NodeStack[StackPtr++]=n;
    Node[n].pal=nodepal(Node[n].pal);
    Node[n].res=True;
}
//----------------------------------------------------------------------------
short existnode(byte n)
{
    TNode *node; short i;

    if (!StackPtr)
        return -1;
    for (i=0; i<StackPtr; i++){
        node=&Node[NodeStack[i]];
        if (node->row==n || node->col==n)
            return node->pal;
    }
    return -1;
}
//----------------------------------------------------------------------------
short numnode(void)
{
    short i,v,m;

    for (v=Node[NodeStack[0]].pal,m=0, i=1; i<StackPtr; i++)
        if (v!=Node[NodeStack[i]].pal){
            m++;
            v=Node[NodeStack[i]].pal;
        }
    return m;
}
//----------------------------------------------------------------------------
short tight(short n)
{
    short i,k,v,pal; TNode *node;

    if (!numnode())
        return 0;
    for (i=k=0,v=pal=-1; i<NodePtr; i++){
        if (!Node[i].res){
            node=&Node[i];
            if (existnode(node->row)!=existnode(node->col)){
                if (node->pal<pal){
                    k=i;
                    pal=node->pal;
                }
            }
        }
    }
    if (0<pal)
        pushnode(k);

    return Node[k].val;
}
//----------------------------------------------------------------------------
short connect(short n, short ptr)
{
    byte *flags;
    TNode *rptr,*cptr;    short i,j,k,v;

    flags=malloc(n);
    memset(flags, 0, n);
    for (StackPtr=i=v=0; i<ptr; i++){
        rptr=&Node[i];
        if (!flags[rptr->row] || !flags[rptr->col]){
            flags[rptr->row]=flags[rptr->col]=True;
            v+=Node[i].val;
            pushnode(i);
#ifdef DESKTOP
            prnnode(&Node[i]);
#endif
        }
        for (j=k=0; j<n; j++)
            if (!flags[j])
                k++;
        if (!k){
            v+=tight(n);
            break;
        }
    }
    free(flags);
    return v;
}
