  int color[MAX], d[MAX], p[MAX];

  for( i = 0 ; i < n ; i++ ){
    color[i] = WHITE;
    d[i] = INFTY;
    p[i] = -1;
  }

  d[0] = 0;

  while( 1 ){
    min = INFTY;
    u = -1;
    for( i = 0 ; i < n ; i++ ){
      if( color[i] != BLACK && min > d[i] ){
	u = i;
	min = d[i];
      }
    }
    if( min == INFTY ) break;
    color[u] = BLACK;
    for( v = 0 ; v < n ; v++ ){
      if( color[v] != BLACK && M[u][v] != INFTY ){
	if( M[u][v] < d[v] ){
	  d[v] = M[u][v];
	  p[v] = u;
	  color[v] = GRAY;
	}
      }
    }
  }

