/*
  Topic12 ProblemA 最小全域木(Minimum Spanning Tree)
  与えられた重み付きグラフ G=(V,E) に対する最小全域木の辺の重みの総和を計算するプログラムを作成する。

  最初の行にGの頂点数nが与えらる。続くn行でGを表すn×nの隣接行列Aが与えられる。
  Aの要素 aij は、頂点iと頂点jを結ぶ辺の重みを表します。ただし、辺がなければ-1で示される。

  Gの最小全域木の辺の重みの総和を1行に出力する。
*/

#include<stdio.h>

#define INFTY 2000
#define BLACK 2
#define GRAY 1
#define WHITE 0

int main()
{
  int i, j, u, v, n, mincost;
  int A[100][100], color[100], d[100], p[100];
  int sum = 0;

  scanf("%d", &n);
  for(i=0;i<n;i++)
    {
      for(j=0;j<n;j++)
	{
	  scanf("%d", &A[i][j]);
	}
    }

  //初期化
  for(i=0;i<n;i++)
    {
      color[i] = WHITE;    
      p[0] = -1;
      d[i] = INFTY;
    }
  d[0] = 0;

  while(1)
    {
      mincost = INFTY;
      for(i=0;i<n;i++)
	{
	  if(color[i] != BLACK && d[i] < mincost)
	    {
	      mincost = d[i];
	      u = i;
	    }
	}

      if(mincost == INFTY)break;

      color[u] = BLACK;

      for(v=0;v<n;v++)
	{
	  if(color[v] != BLACK && A[u][v] != -1)
	    {
	      if(A[u][v] < d[v])
		{
		  d[v] = A[u][v];
		  p[v] = u; color[v] = GRAY;
		}
	    }
	}
    }

  for(i=0;i<n;i++)
    {
      if(p[i] != -1)sum += A[i][p[i]];
    }

  printf("%d\n", sum);
  return 0;
}

