 */
void heapIncreaseKey(int key){

    int i = last_idx;
    EDGE tmp;

    while( i > 1 && heap[i/2].weight < heap[i].weight){
        tmp = heap[i];
        heap[i] = heap[i/2];
        heap[i/2] = tmp;
        i = i/2;
    }

}

