EDGE dequeue(){

    EDGE tmp = heap[1];
    heap[1] = heap[last_idx--];

    /* ??????????´???????????????????????????£????????????heap???????§?????????? */
    maxHeapify(1);
    return tmp;
}


int isEmpty(){
