        return 0;
    }
    else{
        return 1;
    }
}


int Kruskal(int n){
    EDGE A;
    int ans = 0;
    int tmp;

    initialize(n);

    while ( isEmpty() ) {
        A = dequeue();
        if ( !isSame(A.frm, A.to) ){
            unite(A.frm, A.to);
            tmp = ~(A.weight);
            ans += tmp;
        }
    }

    return ans;
}


