	// input
	scanf("%d", &n);
	for( i=0; i<n; i++) {
		for( j=0; j<n; j++) {
			scanf("%d", &MAP[i][j]);
		}
	}

	// output	
	printf("%d\n", MinimumSpanningTree(n) );
	return 0;
}

