int mstForCost( short** g, short n ) {

  int   cost, i, add;
  short di[n], min, minDist;
  char  co[n];

  for( i=0; i<n; i++ ) {
    di[i] = INF;
    co[i] = 0;
  }

  add = 0;
  co[0] = 1;
  cost = 0;
  while( 1 ) {

    for( i=0; i<n; i++ ) {
      if( g[add][i] < di[i] && co[i] == 0) {
	di[i] = g[add][i];
      }
    }


    minDist = INF;
    for( i=0; i<n; i++ ) {
      if( di[i] < minDist  && co[i] == 0 ) {
	minDist = di[i];
	min = i;
      }
    }
    if( minDist == INF ) {
      return cost;
    }

    add = min;
    co[ min ] = 1;
    cost += minDist;

  }

  return 0;

}


