#define MAX_V 100

const int INF = 100000000;
int cost[MAX_V][MAX_V];
int V;

int
prim()
{
	int d[MAX_V];
	int p[MAX_V];
	bool used[MAX_V];
	int minv;
	int u, v;
	int i;

	for (i = 0; i < V; ++i)
	{
		d[i] = INF;
		p[i] = -1;
		used[i] = false;
	}

	d[0] = 0;
	while (true)
	{
		minv = INF;
		v = -1;
		for (u = 0; u < V; ++u)
		{
			if (!used[u] && d[u] < minv)
			{
				v = u;
				minv = d[u];
			}
		}

		if (v == -1)
			break;

		used[v] = true;
		for (u = 0; u < V; ++u)
		{
			if (!used[u] && cost[v][u] < d[u])
			{
				d[u] = cost[v][u];
				p[u] = v;
			}
		}
	}

	int sum = 0;
	for (v = 0; v < V; ++v)
	{
		if (p[v] != -1)
			sum += cost[v][p[v]];
	}

	return sum;
}

