    word pal;
    word res;
}TNode;
//============================================================================
TNode Node[MAX_BUFFER];
TNode *PushNode[MAX_BUFFER];
short NodePtr;
byte  NodeStack[MAX_N];
short StackPtr;
//============================================================================
void prnnode(TNode *node)
{
    printf("row=%3d, col=%3d, val=%4d, pal=%d", node->row, node->col, node->val, node->pal);
    printf("\n");
}
//----------------------------------------------------------------------------
