short match(TNode *dst, TNode *src)
{
    if (dst->row==src->col && dst->col==src->row)
        return 2;
    if (dst->row==src->col || dst->row==src->row ||
        dst->col==src->row || dst->col==src->col)
        return True;
    return False;
}
//----------------------------------------------------------------------------
short nodepal(TNode *node)
{
    short i; TNode *st;

    for (i=0; i<StackPtr; i++){
        st=&Node[NodeStack[i]];
        if (match(st, node)==True){
            if (st->pal<node->pal){
                node->pal=st->pal;
                nodepal(node);//return node->pal;
            }else
            if (node->pal<st->pal){
                st->pal=node->pal;
                nodepal(st);
            }
        }
    }
    return node->pal;
}
//----------------------------------------------------------------------------
void setnode(TNode *node, byte row, byte col, word val)
{
    node->row=row;
    node->col=col;
    node->val=val;
    if (row<col)
        node->pal=row;
    else
        node->pal=col;
    //node->pal=nodepal(node->pal, NodePtr);
}
//============================================================================
short sort(TNode *ary, int n)
{
    short i,j,k,l, cnt; TNode chg;

    for (k=cnt=0, l=n; k<n-1; k++, l--)
    for (i=0,j=1; j<l; i++, j++){
        if (ary[j].val<ary[i].val)
            chg=ary[i], ary[i]=ary[j], ary[j]=chg, cnt++;
	}
    return cnt;
}
//----------------------------------------------------------------------------
//----------------------------------------------------------------------------
void pushnode(byte n)
{
    PushNode[StackPtr]=&Node[n];
    NodeStack[StackPtr++]=n;
    Node[n].pal=nodepal(&Node[n]);
    Node[n].res=True;
}
//----------------------------------------------------------------------------
short existnode(byte n)
{
    TNode *node; short i;

    if (!StackPtr)
        return -1;
    for (i=0; i<StackPtr; i++){
        node=&Node[NodeStack[i]];
        if (node->row==n || node->col==n)
            return node->pal;
    }
    return -1;
}
//----------------------------------------------------------------------------
short numnode(void)
{
    short i,v,m; byte *stack;

    stack=malloc(NodePtr);
    memset(stack, 0, StackPtr);
    for (i=0; i<StackPtr; i++)
        stack[Node[NodeStack[i]].pal]=True;
    for (i=m=0; i<StackPtr; i++)
        if (stack[i])
            m++;
    free(stack);
    return m;
}
//----------------------------------------------------------------------------
short tight(short n)
{
    short i,k,v,val; TNode *node;

    for (v=0; 1<numnode(); ){
        for (i=k=0, val=0x7fff; i<NodePtr; i++){
            if (!Node[i].res){
                node=&Node[i];
                if (existnode(node->row)!=existnode(node->col)){
                    if (node->val<val){
                        k=i;
                        val=node->val;
                    }
                }
            }
        }
        if (val!=0x7fff){
            v+=Node[k].val;
            pushnode(k);
        }
    }
    return v;
}
//----------------------------------------------------------------------------
short connect(short n, short ptr)
{
    byte *flags;
    TNode *rptr,*cptr;    short i,j,k,v;

    flags=malloc(n);
    memset(flags, 0, n);
    for (StackPtr=i=v=0; i<ptr; i++){
        rptr=&Node[i];
        if (!flags[rptr->row] || !flags[rptr->col]){
            flags[rptr->row]=flags[rptr->col]=True;
            v+=Node[i].val;
            pushnode(i);
#ifdef DESKTOP
            prnnode(&Node[i]);
#endif
        }
        for (j=k=0; j<n; j++)
            if (!flags[j])
                k++;
        if (!k){
            v+=tight(n);
            break;
        }
    }
    free(flags);
    return v;
}
