#include<stdio.h>
#include<stdlib.h>
#define N 100
#define LARGE 10000

typedef struct edge{
	int cost;
	int u;
	int v;
}edge;

/*qsort用*/
int cmp(const void *p,const void *q){
	return ((edge*)p)->cost - ((edge*)q)->cost;
}


int find(int u,int par[]){
	if(par[u]==u){
		return u;
	}
}

void merge(int u,int v,int par[]){
	if(par[u] < par[v]){
		if(v!=par[v])
			merge(u,par[par[v]],par);
		par[v]=par[u];
	}
	else {
		if(u!=par[u])
			merge(v,par[par[u]],par);
		par[u]=par[v];
	}
	return;
}



int main(){
	int i,j,n;
	int num=0;/*edgeの個数*/
	int ans=0;
	int a[N][N];
	edge E[LARGE];/*edge*/
	int par[N];/*親の配列*/

	scanf("%d",&n);

	for(i=0;i<n;i++)par[i]=i;


	/*隣接行列の読み込み*/
	for(i=0;i<n;i++){

		for(j=0;j<n;j++){
			scanf("%d",&a[i][j]);
			if(a[i][j]!=-1 && j>=i+1){
				E[num].cost=a[i][j];
				E[num].u=i;
				E[num++].v=j;
			}
		}

	}

	/*edgeのソート*/
	qsort(E,num,sizeof(edge),cmp);

	for(i=0;i<num;i++){
		if(find(E[i].u,par) != find(E[i].v,par)){
			merge(E[i].u,E[i].v,par);
			ans+=E[i].cost;
		}
	}

	printf("%d\n",ans);

	return 0;

}

