	d[r]=0;

	while(Test_Set(A)==0){
		u=Search(d,A);
		A[u]=1;

		for(i=0;i<n;i++){
			if(A[i]==1 || mat[u][i]==-1) continue;
			if(mat[u][i]<d[i]) d[i]=mat[u][i];
		}
	}

}

