  for(i=0;i<n;i++){
    d[i]=INF;
    pi[i]=NIL;
    color[i]=WHITE;
  }
  d[0]=0;

  while(1){
    min=INF;
    u=NIL;
    for(i=0;i<n;i++){
      if(color[i]!=BLACK && d[i]<min){
        u=i;
        min=d[i];
      }
    }
    if(u==NIL) break;
    color[u]=BLACK;

    for(v=0;v<n;v++){
      if(color[v]!=BLACK && a[u][v]!=INF){
        if(d[v]>a[u][v]){
          d[v]=a[u][v];
          pi[v]=u;
          color[v]=GRAY;
        }
      }
    }
  }
  for(i=0;i<n;i++){
    if(pi[i]!=NIL){
      sum+=a[i][pi[i]];
    }
  }
  return sum;
}

