#define INFTY 1000000000
#define MAX 100

typedef struct{
  int color; //全て白(0)に初期化済み
  int id;
  int distance;
  int parent;
}DOT;

DOT A[MAX];//本体
int G[MAX][MAX];//グラフ

int MinTree(int n){
  int total=0;
  int min_box;
  int flag;
  int i;
  int u,v;

  A[0].distance=0;

  while(1){
    int min_box=INFTY;
    int flag=0;
    int u,v;

    for(i=0;i<n;i++){
      if(A[i].color!=BLACK && A[i].distance<min_box){//グループで最も最小の手を持つ先にある番号

	min_box=A[i].distance;
	u=i;
	flag=1;
      }
    }

    if(flag==0)break;
    A[u].color=BLACK;//最少の手

    for(v=0;v<n;v++){//uの隣vを調べつくす
      if(G[u][v]!=-1 && A[v].color!=BLACK)//まだグループではなく、存在する
	if(A[v].distance>G[u][v]){//A[v]はvからuへの最短を記録したい 
	  A[v].distance=G[u][v];
	  A[v].parent=u;
	  A[v].color=GRAY;
	}
    }
  }



  for(v=1;v<n;v++){
    total+=G[v][A[v].parent];
  }
  return total;//最少ルートで回ったときの距離の合計
}


