#include <stdio.h>
#include <stdlib.h>

typedef struct {
	int parent, rank;
} Node;
typedef struct {
	int from, to, w;
} Edge;

Node node[100];
Edge edge[10000];
int e;

int compare(const void *a, const void *b) {
	return ((Edge *)a)->w - ((Edge *)b)->w;
}

void init(int n) {
	int i;
	for (i = 0; i < n; i++) {
		node[i].parent = i;
		node[i].rank = 0;
	}
}

int find(int x) {
	return node[x].parent != x ? node[x].parent = find(node[x].parent) : x;
}

void unite(int x, int y) {
	int xr = find(x), yr = find(y);

	if (node[xr].rank < node[yr].rank)
		node[xr].parent = yr;
	else {
		node[yr].parent = xr;
		if (node[xr].rank == node[yr].rank)
			node[xr].rank++;
	}
}

int kruskal(int v, int e) {
	int i;
	int sum;

	qsort(edge, e, sizeof(Edge), &compare);

	init(v);

	sum = 0;
	for (i = 0; i < e; i++)
		if (find(edge[i].from) != find(edge[i].to)) {
			unite(edge[i].from, edge[i].to);
			sum += edge[i].w;
		}

	return sum;
}

