#define INFINITE 100000000
// Maximum number of nodes
#define NODENUM 1000
// 隣接行列
int dist[NODENUM][NODENUM];
int cost[NODENUM];
int nearest[NODENUM];

int prim(int n)
{
    int i;
    int totalWeight = 0;
    bool visited[NODENUM];
    for (i = 0; i < NODENUM; i++)
        visited[i] = false;
    visited[0] = true;
    for (i = 0; i < n; i++) {
        cost[i] = dist[0][i];
        nearest[i] = 0;
    }
    while (1) {
        int min = INFINITE;
        int minID;
        for (i = 0; i < n; i++) {
            if (visited[i]) continue;
            if (min > cost[i]) {
                min = cost[i];
                minID = i;
            }
        }
        if (min == INFINITE) break;
        visited[minID] = true;
        totalWeight += dist[minID][nearest[minID]];
        for (i = 0; i < n; i++) {
            if (dist[minID][i] < cost[i]) {
                cost[i] = dist[minID][i];
                nearest[i] = minID;
            }
        }
    }
    return totalWeight;
}

