	for(i=0;i<n;i++){

		for(j=0;j<n;j++){
			scanf("%d",&a[i][j]);
			if(a[i][j]!=-1 && j>=i+1){
				E[num].cost=a[i][j];
				E[num].u=i;
				E[num++].v=j;
			}
		}

	}

	/*edgeのソート*/
	qsort(E,num,sizeof(edge),cmp);

	for(i=0;i<num;i++){
		if(find(E[i].u,b) != find(E[i].v,b)){
			merge(E[i].u,E[i].v,b);
			ans+=E[i].cost;
		}
	}

	printf("%d\n",ans);

	return 0;

}

