  while(1){
    int mincost = INFTY;
    int u;

    for(i = 0; i < n; i++){  //costが最小のノードuを選択
      if(!visited[i]==GRAY && cost[i]<mincost){
	mincost = cost[i];
	u = i;
      }
    }

    if( mincost == INFTY ) break;

    visited[u] = GRAY;

    int v;

    for(v = 0; v < n; v++){
      if(visited[v]==GRAY || M[u][v]==INFTY) continue;
      if(M[u][v] < cost[v]){
	cost[v] = M[u][v];
	pi[v] = u;
      }
    }

  }

  sum = 0;

  for ( i = 0; i < n; i++ ){
    if ( pi[i] != -1 ) sum += M[i][pi[i]];
  }

  printf("%d\n", sum);

  return 0;
}


