    int n, i, j, e;

    scanf("%d\n", &n);
    V = n;
    for (i = 1; i <= n; i++) {
        for (j = 1; j <= n; j++) {
            scanf("%d", &e);
            cost[i][j] = (e == -1) ? INF : e;
        }
    }

    printf("%d\n", solve());

    return 0;
}

