    for(i = 0; i < num; i++) {
      if(!checked[i]) continue;
      struct list *head = &graph[i];
      struct list *tmp;
      for(tmp = head->next; tmp != head; tmp = tmp->next) {
        if(checked[tmp->dst]) continue;
        if(min > tmp->cost) {
          min_node = tmp->dst;
          min = tmp->cost;
        }
      }
    }
    if(min_node != -1) enqueue(min_node, min);
  }
  printf("%d\n", sum);
  return 0;
}

