	scanf("%d", &n);

	PAR = (int *)malloc(sizeof(int) * n);
	mark = (int *)malloc(sizeof(int) * n);
	for(i = 0; i < n; i++)
		mark[i] = -1;
	Init(n);

	side = (SIDE_T *)malloc(sizeof(SIDE_T) * n * n);

	_graph = (int *)malloc(sizeof(int) * n * n);
	graph = (int **)malloc(sizeof(int *) * n);
	for(i = 0; i < n; i++)
		graph[i] = _graph + (i * n);

	for(i = 0; i < n; i++)
		for(j = 0; j < n; j++)
			scanf("%d", &graph[i][j]);

	// 辺として取り出す
	count = 0;
	for(i = 0; i < n; i++){
		for(j = 0; j < n; j++){
			if(i <= j && graph[i][j] != -1){
				side[count].cost = graph[i][j];
				side[count].from = i;
				side[count++].to = j;
			}
