/* Prim's Algorithm */
int prim(int r) {
  int i, u, v;
  int mincost, sum = 0;
  for ( u = 0; u < n; u++ ) {
    color[u] = WHITE;
    d[u] = INFTY;
    pi[u] = NIL;
  }
  d[r] = 0;

  while ( 1 ) {
    mincost = INFTY;
    for ( i = 0; i < n; i++ ) {
      if ( color[i] != BLACK && d[i] < mincost ) {
        mincost = d[i];
        u = i;
      }
    }

    if ( mincost == INFTY ) break;

    color[u] = BLACK;

    for ( v = 0; v < n; v++ ) {
      if ( color[v] != BLACK && AM[u][v] != INFTY ) {
        if ( AM[u][v] < d[v] ) {
          d[v] = AM[u][v];
          pi[v] = u;
          color[v] = GRAY;
        }
      }
    }
  }

  for ( i = 0; i < n; i++ )
    if ( pi[i] != NIL )
      sum += AM[i][pi[i]];

  return sum;
}

