#include<stdio.h>

#define S 100

typedef struct EDGE{
	int cost;
	int node[2];	//always (node[0] <= node[1]).
}Edge;

Edge heap[S*S];	//minimum heap.
int N;	//number of elements in heap.
int n;
int group[S];
int numGroup;	//number of groups. when it is 1, all nodes are connected.
int cost;

void setEdge(Edge *dst, const Edge *src){
	dst->cost = src->cost;
	dst->node[0] = src->node[0];
	dst->node[1] = src->node[1];
}

//e1->cost < e2->cost:-1
//e1->cost == e2->cost:0
//e1->cost > e2->cost:1
int cmpEdge(Edge *e1, Edge *e2){
	return (e1->cost < e2->cost?-1:0) + (e1->cost > e2->cost?1:0);
}

void swapEdge(Edge *e1, Edge *e2){
	int temp;
	temp = e1->cost; e1->cost = e2->cost; e2->cost = temp;
	temp = e1->node[0]; e1->node[0] = e2->node[0]; e2->node[0] = temp;
	temp = e1->node[1]; e1->node[1] = e2->node[1]; e2->node[1] = temp;
	return;
}

void up(int i){
	if( i <= 1 ){ return; }
	if( cmpEdge(&heap[i], &heap[i/2]) == -1 ){
		swapEdge(&heap[i], &heap[i/2]);
		up(i/2);
	}
	return;
}

void down(int i){
	int j;
	if( 2*i > N ){ return; }
	if( cmpEdge(&heap[2*i], &heap[2*i+1]) == -1 ){
		j = 2*i;
	}else{
		j = 2*i+1;
	}
	if( cmpEdge(&heap[i], &heap[j]) == 1 ){
		swapEdge(&heap[i], &heap[j]);
		down(j);
	}
	return;
}

void add(Edge *e){
	N++;
	setEdge(&heap[N], e);
	up(N);
	return;
}

void delete(){
	if( N < 1 ){ return; }
	heap[1] = heap[N];
	N--;
	down(1);
	return;
}

void init(){
	int i;
	N = 0;
	for( i = 0; i < S; i++ ){ group[i] = i; }
	cost = 0;
	return;
}

void input(){
	int i, j;
	Edge e;
	scanf("%d", &n);
	numGroup = n;
	for( i = 0; i < n; i++ ){
		for( j = 0; j < n; j++ ){
			scanf("%d", &e.cost);
			if( i > j ){ continue; }
			if( e.cost < 0 ){ continue; }
			e.node[0] = i;
			e.node[1] = j;
			add(&e);
		}
	}
	return;
}

void printGroup(){
	int i;
	for( i = 0; i < n; i++ ){ printf("%d ", group[i]); }
	printf("\n");
}

//the group number change from en2 to en1.
void changeGroup(int en1, int en2){
	int i;
	for( i = 0; i < n; i++ ){
		if( group[i] == en2 ){ group[i] = en1; }
	}
	//printGroup();
	return;
}

void get(){
	Edge e;
	while( numGroup > 1 && N > 0 ){
		setEdge(&e, &heap[1]);
		delete();
		//printf("%d:%d,%d\n", e.cost, e.node[0], e.node[1]);
		if( group[e.node[0]] == group[e.node[1]] ){ continue; }
		//printf("select\n");
		cost += e.cost;
		changeGroup(group[e.node[0]], group[e.node[1]]);
	}
}

void print(){
	printf("%d\n", cost);
	return;
}

int main(){
	init();
	input();
	get();
	print();
	return 0;
}

