#include<stdio.h>

#define N 100
#define Gard 100000001
#define Nothing -1
#define Initial 0
#define Medium 1
#define End 2

int main(){
  int loop,Min=0,judge,result=0,temp=0;
  int i,j;
  int Graph[N][N];
  int Ver[N];
  int Pdisc[N];
  int Fin[N];

  scanf("%d",&loop);
  for(i=0;i<loop;i++){

    for(j=0;j<loop;j++){
      scanf("%d",&Graph[i][j]);
    }
  }

  for(i=0;i<loop;i++){
    Ver[i]=Gard;
    Pdisc[i]=Nothing;
    Fin[i]=Initial;
  }

  Ver[0]=0;

  while(1){
    Min=Gard;
    judge=Nothing;

    for(i=0;i<loop;i++){

      if((Fin[i]!=End) && (Ver[i]<Min)){
	Min=Ver[i];
	judge=i;
      }
    }

    if(judge==Nothing){
      break;
    }

    Fin[judge]=End;

    for(i=0;i<loop;i++){

      if((Fin[i]!=End) && (Graph[judge][i]!=Nothing)){
	if(Graph[judge][i]<Ver[i]){
	  Ver[i]=Graph[judge][i];
	  Pdisc[i]=judge;
	  Fin[i]=Medium;
	}
      }
    }

  }


  for(i=0;i<loop;i++){

    if(Pdisc[i]!=Nothing){
      temp=Pdisc[i];
      result+=Graph[i][temp];
    }
  }


  printf("%d\n",result);

  return 0;
}

