int SumWeightMST()
{
  int i, j;
  int join = 0;
  int d, mini_d;
  int sum = 0;

  // Set default
  for(i = 0; i < n; i++)
    {
      V[i].distance = INF;
      V[i].visitFlag = 0;
    }

  // Make minimum spanning Tree
  for(i = 0; i < n; i++)
    {
      V[join].visitFlag = 1;

      // Set  new distance
      for(j = 0; j < n; j++)
	{
	  d = V[join].Edge[j];

	  if(V[j].visitFlag == 0 && d < V[j].distance && d != -1)
	    V[j].distance = d;
	}

      // Serch nearest Vertex
      mini_d = INF;
      for(j = 0; j < n; j++)
	{
	  if(mini_d > V[j].distance && V[j].visitFlag == 0) 
	    {
	      mini_d = V[j].distance;
	      join = j;
	    }
	}
      if(mini_d != INF)
	sum += mini_d;
    }

  return sum;
}

