				if(MAP[ color[i] ][j] < min) {
					min = MAP[ color[i] ][j];
					min_node = j;
				}
			}
		}

		// ノードk+1個の最小全域木の作成
		if(k < n) {
			color[k] = min_node;
			colorflag[min_node] = 1;
			sum += min;
		}
		else break;

		k++;
	}

	return sum;
}

