int Search_path(int **array,int *flag,int n){
  int index,num,i,j,min=INT_MAX,sum=0;
  int passed[n],pass_count=1;//passed[]:既に通ったnode
  index=0;
  flag[index] = 1;
  passed[0]=index;
  while(1){
    num = -1;
    min = INT_MAX;
    for(j=0;j<pass_count;j++){
      index=passed[j];
      for(i=0;i<n;i++){
	if(flag[i] == 0 && min > array[index][i] && array[index][i] > -1){//通ったnodeから繋がっているnodeがまだ通ってないかつ、一番costが少ない所を選ぶ
	  min = array[index][i];
	  num = i;
	}
      }
    }
    if(num == -1)break;
    flag[num]=1;
    passed[pass_count++]=num;//通ったnodeを記録
    sum +=min;//最小コストを全て足す
  }
  return sum;
}

