		 for (j = 0; j < memo[i]; j++) {
			if (LIST[i][j].length == (*C) && ((nord[i] == 0 && nord[LIST[i][j].next] == 1) || (nord[LIST[i][j].next] == 0 && nord[i] == 1))) {
			   nord[i] = 1;
			   nord[LIST[i][j].next] = 1;
			   *C = 0;
			   return LIST[i][j].length;
			}
		 }
	  }
   }
   *C = *C + 1;
   return searchmin(n, C);
}

