    fun find(_n: Int): Int {
        if (_n == uf[_n]) {
            return _n
        } else {
            uf[_n] = find(uf[_n])
            return uf[_n]
        }
    }

    fun isSame(_i: Int, _j: Int): Boolean {
        return find(_i) == find(_j)
    }

    fun join(_i: Int, _j: Int) {
        uf[find(_i)] = find(_j)
