class Main {

    companion object {
        private val graphMatrix = arrayListOf<List<Int>>()


        private val nodeList = arrayListOf<Node>()

        fun init() {
            val num = readLine()!!.toInt()

            for (index in 1..num) {
                val inputs = readLine()!!.split(" ").subList(1, num + 1).map {
                    if (it == "-1") Int.MAX_VALUE else it.toInt()
                }

                graphMatrix.add(inputs)

                nodeList.add(Node())
            }
        }

        fun display() {
            println(nodeList.sumBy {
                it.minCost
            })
        }

        /**
         * 深さ優先
         */
        fun execute() {

            nodeList[0].minCost = 0

            while (true) {
                // 黒ではなく、なおかつ最小のノードを取得
                var minCost = Int.MAX_VALUE
                var minIndex: Int? = null
                for (index in 1..nodeList.size) {
                    if (nodeList[index - 1].color != Node.Color.BLACK && minCost > nodeList[index - 1].minCost) {
                        minCost = nodeList[index - 1].minCost
                        minIndex = index
                    }
                }

                // 一つもないので終了
                if (minCost == Int.MAX_VALUE || minIndex == null) {
                    break
                }

                // 色を変える
                nodeList[minIndex - 1].color = Node.Color.BLACK

                graphMatrix[minIndex - 1].forEachIndexed { index, cost ->
                    // 調査対象かどうかチェック
                    if (nodeList[index].color != Node.Color.BLACK && cost != Int.MAX_VALUE) {

                        // もともとのコストより小さいかチェック
                        val originalCost = nodeList[index].minCost
                        val foundedCost = graphMatrix[index][minIndex!! - 1]
                        if (originalCost > foundedCost) {
                            nodeList[index].color = Node.Color.GRAY
                            nodeList[index].minCost = foundedCost
                        }
                    }
                }
            }
        }
    }
}


