    val c = Array(n) { 0 }
    val d = Array(n) { inf }
    val p = Array(n) { -1 }
    d[0] = 0
    while (true) {
        var mincost = inf
        var u = -1
        for (i in 0 until n) {
            if (c[i] != 2 && d[i] < mincost) {
                mincost = d[i]
                u = i
            }
        }
        if (u == -1)
            break
        c[u] = 2
        for (j in 0 until n) {
            if (c[j] != 2 && a[u][j] != inf) {
