class Edge implements Comparable<Edge>{
	int x;
	int y;
	int dist;
	public Edge(int x, int y, int d){
		this.x = x;
		this.y = y;
		this.dist = d;
	}
	@Override
 	public int compareTo(Edge other) {
		return this.dist - other.dist;
	}
	@Override
	public String toString(){
		return "x: " + x + " y : " + y + " dist : " + dist;
	}
}
class AdjacencyMatrices{
	int pointNum;
	ArrayList<Edge> edgeList = new ArrayList<Edge>();
	public AdjacencyMatrices(int n){
		pointNum = n;
	}
	public void readMatrix(Scanner scan){
		for(int i=0; i<pointNum; i++)
			for(int j=0; j< pointNum; j++){
				int dist = scan.nextInt();
				if(j > i && dist>0)
					edgeList.add(new Edge(i, j, dist));
		}
	}
	public void printEdge(){

		for(int i=0; i<edgeList.size(); i++)
			System.out.println(edgeList.get(i));
	}
	public Iterator<Edge> getIter(){
		Collections.sort(edgeList);
		return edgeList.iterator();
	}

}
class UnionFind{
    int[] index;
    public UnionFind(int n){
        index = new int[n];
        for(int i=0; i<n; i++)
            index[i] = i;
    }
    int find(int x){
        if(index[x]==x)
            return x;
        else
            return find(index[x]);
    }
    boolean same(int x, int y){
        return find(x) == find(y);
    }
    void union(int x, int y){
