import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;


public class Main{

	@SuppressWarnings("unchecked")
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		nPoint = in.nextInt();

		List<E> lE = new ArrayList<E>();
		for (int i=0;i<nPoint;i++) {
			for (int j=0;j<nPoint;j++) {
				int d = in.nextInt();
				if (d>=0) lE.add(new E(i, j, d));
			}
		}
		arEdge = lE.toArray(new E[0]);

		System.out.println(kruskal(0));
	}

	static int nPoint;
	static E[] arEdge;

	// s is index of start point
	static long kruskal(int s) {
		initUF(nPoint);
		Arrays.sort(arEdge);

		long res=0;
		Set<E> already = new HashSet<E>();
		int index = 0;
		while (already.size() != nPoint-1) {
			E next = arEdge[index++];
			if (!same(next.from, next.to)) {
				unite(next.from, next.to);
				already.add(next);
				res += next.dist;
			}
		}
		return res;
	}

	static class E implements Comparable<E> {
		int from; int to; int dist;
		public E(int from, int to, int dist) {this.from=from; this.to=to; this.dist=dist;}
		public int compareTo(E p) {return this.dist - p.dist;}
	}

	/// Union-Find
	static int[] par;
	static int[] rank;

	static void initUF(int n) {
		par = new int[n];
		rank = new int[n];
		for (int i=0;i<n;i++){
			par[i] = i;
			rank[i] = 1;
		}
	}

	static int root(int n) {
		if (par[n]==n) {
			return n;
		} else {
			return (par[n] = root(par[n]));
		}
	}

	static boolean same(int i, int j) {
		return root(i)==root(j);
	}

	static void unite(int i, int j) {
		int x = root(i);
		int y = root(j);

		if (rank[x]>rank[y]) {
			par[y] = x;
		} else {
			par[x] = y;
			if (rank[x]==rank[y]) rank[x]++;
		}
	}


}

import java.util.*;

class Main {
    enum Color {
        WHITE,
        GRAY,
        BLACK,
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine());

        int[][] weight = new int[n][n];

        for (int i = 0; i < n; i++) {
            String[] line = scanner.nextLine().split(" ", n+1);
            for (int j = 0; j < n; j++) {
                int a = Integer.parseInt(line[j+1]);
                weight[i][j] = (a == -1 ? Integer.MAX_VALUE : a);
            }
        }

        System.out.println(prim(weight, n));
    }

    private static int prim(int[][] weight, int n) {
        Color[] color = new Color[n];
        int[] dMin = new int[n];
        int[] parent = new int[n];

        Arrays.fill(dMin, Integer.MAX_VALUE);
        Arrays.fill(parent, -1);
        Arrays.fill(color, Color.WHITE);

        dMin[0] = 0;

        while (true) {
            // linear search
            int minInd = -1;
            int minCost = Integer.MAX_VALUE;
            for (int i = 0; i < n; i++) {
                if (color[i] != Color.BLACK && dMin[i] < minCost) {
                    minInd = i;
                    minCost = dMin[i];
                }
            }

            if (minInd == -1)
                break;

            color[minInd] = Color.BLACK;

            for (int v = 0; v < n; v++) {
                if (color[v] != Color.BLACK && weight[minInd][v] != Integer.MAX_VALUE
                        && weight[minInd][v] < dMin[v]) {
                    dMin[v] = weight[minInd][v];
                    parent[v] = minInd;
                    color[v] = Color.GRAY;
                }
            }
        }

        int result = 0;
        for (int i = 0; i < n; i++) {
            if (parent[i] != -1) {
                result += dMin[i];
                //result += weight[i][parent[i]];
            }
        }
        return result;
    }
}

