/**
 * Graph II - Minimum Spanning Tree
 */
public class Main {

	static final int INF = 1 << 29;

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String line;

		int n = parseInt(br.readLine());

		int[][] a = new int[n][n];

		for (int i = 0; i < n; i++) {
			StringTokenizer st = new StringTokenizer(br.readLine());
			for (int j = 0; j < n; j++) {
				a[i][j] = parseInt(st.nextToken());
			}
		}

		//solve
		int cost = 0;
		int size = 0;
		boolean[] S = new boolean[n];

		S[0] = true;
		size++;

		while (size < n) {
			int min = INF;
			int v = -1;
			for (int i = 0; i < n; i++) {
				if (S[i]) {
					for (int j = 0; j < n; j++) {
						if (!S[j] && a[i][j] != -1 && a[i][j] < min) {
							min = a[i][j];
							v = j;
						}
					}
				}
			}
			S[v] = true;
			size++;
			cost += min;
		}

		System.out.println(cost);
	}
}

import java.util.Scanner;

public class Main {
    static int WHITE = 0;
    static int GRAY = 1;
    static int BLACK = 2;
    public static void main(String[] args){
        Scanner input = new Scanner(System.in);
        int n = input.nextInt();
        int[][] G = new int[n][n];
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < n; j++) {
                G[i][j] = input.nextInt();
            }
        }
        int[] p = new int[n];
        int[] d = new int[n];
        int[] color = new int[n];

        // 初始化
        for(int i = 0; i < n; i++) {
            d[i] = Integer.MAX_VALUE;
            p[i] = - 1;
            color[i] = WHITE;
        }

        d[0] = 0;
        int totalCost = 0;

        // 不断添加点，直到所有点都加入MST中
        while(true) {
            int minCost = Integer.MAX_VALUE;
            int u = 0;
            // 找到当前T内顶点与V-T内顶点的的边中最小的边
            for(int i = 0; i < n; i++){
                if(color[i] != BLACK && d[i] < minCost) {
                    minCost = d[i];
                    u = i;
                }
            }
            if(minCost == Integer.MAX_VALUE) {
                break;
            }
            // 将对应顶点和边加入T
            color[u] = BLACK;
            totalCost += minCost;

            // 更新新顶点加入后T内顶点与V-T内顶点的边的距离
            for(int v = 0; v < n; v++){
                if(color[v] != BLACK && G[u][v] != -1) {
                    if(G[u][v] < d[v]) {
                        d[v] = G[u][v];
                        p[v] = u;
                        color[v] = GRAY;
                    }
                }
            }
        }
        System.out.println(totalCost);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

	private enum COLOR {WHITE,GRAY,BLACK};
	private static final int INFINITY = 1 << 30;

	public static void main(String[] args) throws IOException {
		new Main().run();
	}

	private void run() throws IOException {
		BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(reader.readLine());
		int[][] m = new int[n][n];
		for (int i = 0; i < n; i++) {
			StringTokenizer st = new StringTokenizer(reader.readLine());
			for (int j = 0; j < n; j++) {
				int weight = Integer.parseInt(st.nextToken());
				m[i][j] = weight==-1?INFINITY:weight;
			}
		}
		reader.close();
		System.out.println(prim(n, m));
	}

	private int prim(int n, int[][] m) {

		COLOR[] colors = new COLOR[n];
		int[] d = new int[n];
		int[] p = new int[n];
		for (int i = 0; i < n; i++) {
			colors[i] = COLOR.WHITE;
			d[i] = INFINITY;
			p[i] = -1;
		}

		d[0] = 0;
		while (true) {
			int minv = INFINITY;
			int u = -1;
			for (int i = 0; i < n; i++) {
				if (colors[i] == COLOR.BLACK) continue;
				if (minv > d[i]) {
					minv = d[i];
					u = i;
				}
			}
			if (u == -1) break;
			colors[u] = COLOR.BLACK;
			for (int v = 0; v < n; v++) {
				if (colors[v] == COLOR.BLACK) continue;
				if (m[u][v] == INFINITY) continue;
				if (d[v] > m[u][v]) {
					d[v] = m[u][v];
					p[v] = u;
				}
			}
		}
		int cost = 0;
		for (int i = 0; i < n; i++) {
			if (p[i] != -1) cost += m[i][p[i]];
		}
		return cost;
	}
}

