        }

        int sumCost = 0;
        boolean[] used = new boolean[n+1];
        // minCostFromMST[i]: 作成中 MST(どの頂点でもよい) から,未訪問の頂点 i に移動するための最小コスト。
        int[] minCostFromTempMST = new int[n+1]; 

        for (int i = 1; i <= n; i++) {
            minCostFromTempMST[i] = MAX;
        }
        // 頂点1以外は何で初期化する? -> とりあえず-1 -> minCostとの比較で支障が出そうなのでMAX
        minCostFromTempMST[1] = 0;

        while (true) {
            // 次に訪問する頂点と, 作成中MSTとG-MSTの中で最小コストの辺のコスト
            int next = -1;
            int minCost = MAX;

            // 「未訪問で、作成中MSTからもっとも近い頂点」をnextにする。初回は頂点1が選ばれる
            for (int i = 1; i <= n; i++) {
                if (!used[i] && minCostFromTempMST[i] < minCost) {
                    next = i;
                    minCost = minCostFromTempMST[i];
                }
            }
            if (next == -1) break;

            used[next] = true;
            sumCost += minCostFromTempMST[next];
            for (int i = 1; i <= n; i++) {
                // 「未訪問で、nextと隣接する頂点」 の minCostFromTempMST を更新する。
                if (!used[i] && w[next][i] != MAX) {
                    minCostFromTempMST[i] = Math.min(minCostFromTempMST[i], w[next][i]);
                }
            }
        }
        System.out.println(sumCost);
    }
}

import java.util.Scanner;

public class Main{
    public static final int WHITE = 0;
    public static final int GRAY = 1;
    public static final int BLACK = 2;
    public static final int INF = Integer.MAX_VALUE;


    public Main() {

    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[][] G = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int w = sc.nextInt();
                G[i][j] = (w == -1) ? INF : w;
            }
        }
        int res = prim(n, G);
        System.out.println(res);


    }

    private static int prim(int n, int[][] G) {
        int u;
        int minv;
        int[] d = new int[n];
        int[] p = new int[n];
        int[] color = new int[n];

        for (int i = 0; i < n; i++) {
            d[i] = INF;
            p[i] = -1;
            color[i] = WHITE;
        }

        d[0] = 0;

        while (true) {
            minv = INF;
            u = -1;
            for (int i = 0; i < n; i++) {
                if (d[i] < minv && color[i] != BLACK) {
                    u = i;
                    minv = d[i];
                }
            }
            if(u==-1){
                break;
            }
            color[u]=BLACK;

            for(int v=0;v<n;v++){
                if(color[v] != BLACK && G[u][v] != INF){
                    if(d[v] > G[u][v]) {
                        d[v] = G[u][v];
                        p[v] = u;
                        color[v] = GRAY;
                    }
                }
            }
        }
        int sum = 0;
        for(int i = 0; i < n; i++){
            if(p[i] != -1){
                sum += G[i][p[i]];
            }
        }
        return sum;
    }
}

