    private static int buflen = 0;

    public static void main(String[] args) {
        final int MAX = Integer.MAX_VALUE;
        int n = ni();
        int[][] g = new int[n][n];
        for (int i = 0; i < g.length; i++) {
            for (int j = 0; j < g[i].length; j++) {
                int tmp = ni();
                g[i][j] = tmp == -1 ? MAX : tmp;
            }
        }

        boolean[] b = new boolean[n];
        int[] d = new int[n];
        Arrays.fill(d, MAX);
        int[] p = new int[n];

        d[0] = 0;
        p[0] = -1;
        while (true) {
            int tmpMinCost = MAX;
            int u = 0;
            for (int i = 0; i < n; i++) {
                if (!b[i] && d[i] < tmpMinCost) {
                    u = i;
                    tmpMinCost = d[i];
                }
            }

            if (tmpMinCost == MAX) break;

            b[u] = true;
            for (int v = 0; v < n; v++) {
                if (!b[v] && g[u][v] != MAX) { // 未訪問かつ u と v の間に辺がある
                    if (g[u][v] < d[v]) {
                        d[v] = g[u][v];
                        p[v] = u;
                    }
                }
            }
        }

        int sum = 0;
        for (int i = 0; i < n; i++) {
            if (p[i] != -1) sum += g[i][p[i]];
        }
        ps.println(sum);
