import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

	private enum COLOR {WHITE,GRAY,BLACK};
	private static final int INFINITY = 1 << 30;

	public static void main(String[] args) throws IOException {
		new Main().run();
	}

	private void run() throws IOException {
		BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(reader.readLine());
		int[][] m = new int[n][n];
		for (int i = 0; i < n; i++) {
			StringTokenizer st = new StringTokenizer(reader.readLine());
			for (int j = 0; j < n; j++) {
				m[i][j] = Integer.parseInt(st.nextToken());
			}
		}
		reader.close();
		System.out.println(prim(n, m));
	}

	private int prim(int n, int[][] m) {

		COLOR[] colors = new COLOR[n];
		int[] d = new int[n];
		int[] p = new int[n];
		for (int i = 0; i < n; i++) {
			colors[i] = COLOR.WHITE;
			d[i] = INFINITY;
			p[i] = -1;
		}

		d[0] = 0;
		while (true) {
			int minv = INFINITY;
			int u = -1;
			for (int i = 0; i < n; i++) {
				if (colors[i] == COLOR.BLACK) continue;
				if (minv > d[i]) {
					minv = d[i];
					u = i;
				}
			}
			if (u == -1) break;
			colors[u] = COLOR.BLACK;
			for (int v = 0; v < n; v++) {
				if (colors[v] == COLOR.BLACK) continue;
				if (m[u][v] == -1) continue;
				if (d[v] > m[u][v]) {
					d[v] = m[u][v];
					p[v] = u;
				}
			}
		}
		int cost = 0;
		for (int i = 0; i < n; i++) {
			if (p[i] != -1) cost += m[i][p[i]];
		}
		return cost;
	}
}

// ALDS1_12_A - MST (Kruskal's)

import java.util.*;

class UF {
  int[] A;

  UF(int n) {
    A = new int[n];
    Arrays.fill(A, -1);
  }

  int find(int k) {
    if (A[k] < 0) {
      return k;
    } else {
      A[k] = find(A[k]);
      return A[k];
    }
  }

  void union(int k, int j) {
    int rk = find(k);
    int rj = find(j);
    if (A[rk] < A[rj]) { // rk has more elements
      A[rk] += A[rj]; // update rk's size
      A[rj] = rk; // point the set rk to rj
    } else {
      A[rj] += A[rk];
      A[rk] = rj;
    }
  }
}

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    UF uf = new UF(n);
    List<int[]> edges = new ArrayList<int[]>();
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        int weight = sc.nextInt();
        if (weight != -1) {
          edges.add(new int[] {i, j, weight});
        }
      }
    }
    Collections.sort(
        edges,
        new Comparator<int[]>() {
          public int compare(int[] e1, int[] e2) {
            return Integer.compare(e1[2], e2[2]);
          }
        });
    int w = 0;
    for (int[] e : edges) {
      int f1 = uf.find(e[0]);
      int f2 = uf.find(e[1]);
      if (f1 != f2) {
        w += e[2];
        uf.union(f1, f2);
      }
    }
    System.out.println(w);
  }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.StringTokenizer;

class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Task solver = new Task();
        solver.solve(in, out);
        out.close();
    }

    static class Task {
        int N;

        void solve(InputReader in, PrintWriter out) {
            N = in.nextInt();
            Kruskal ksk = new Kruskal(N);

            for (int i = 0; i < N; ++i) {
                for (int j = 0; j < N; ++j) {
                    int w = in.nextInt();
                    if (w >= 0) ksk.addEdge(i, j, w);
                }
            }

            ksk.setMST();
            out.println(ksk.getTotalCost());
        }
    }

    static class Kruskal {
        private int totalCost;

        private UnionFind uf;
        private List<Edge> edges;
        private List<Edge> mst;

        public Kruskal(int n) {
            this.totalCost = 0;
            this.uf = new UnionFind(n);
            this.edges = new ArrayList<>();
            this.mst = new ArrayList<>();
        }

        public void setMST() {
            Collections.sort(edges);
            for (Edge e : edges) {
                if (!uf.same(e.src, e.dest)) {
                    uf.unite(e.src, e.dest);
                    totalCost += e.weight;
                    mst.add(e);
                }
            }
        }

        public int getTotalCost() {
            return totalCost;
        }

        public List<Edge> getEdges() {
            return mst;
        }

        public void addEdge(int u, int v, int w) {
            edges.add(new Edge(u, v, w));
        }

        public class Edge implements Comparable<Edge> {
            private int src;
            private int dest;
            private int weight;

            public Edge(int s, int d, int w) {
                this.src = s;
                this.dest = d;
                this.weight = w;
            }

            @Override
            public int compareTo(Edge e) {
                return this.weight - e.weight;
            }
        }

        private class UnionFind {
            private int[] rank, parent;

            public UnionFind(int size) {
                this.rank = new int[size];
                this.parent = new int[size];
                for (int i = 0; i < size; ++i) {
                    parent[i] = i;
                    rank[i] = 0;
                }
            }

            public boolean same(int x, int y) {
                return root(x) == root(y);
            }

            public void unite(int x, int y) {
                int a = root(x);
                int b = root(y);

                if (rank[a] < rank[b]) {
                    int tmp = a;
                    a = b;
                    b = tmp;
                }

                parent[b] = a;
                if (rank[a] == rank[b])
                    rank[a]++;
            }

            public int root(int x) {
                if (parent[x] != x) {
                    parent[x] = root(parent[x]);
                }
                return parent[x];
            }
        }
    }
    static class InputReader {
        static int BUFSIZE = 32768;

        BufferedReader reader;
        StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), BUFSIZE);
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; ++i) {
                arr[i] = nextInt();
            }
            return arr;
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        long[] nextLongArray(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; ++i) {
                arr[i] = nextLong();
            }
            return arr;
        }
    }
}

