		int u;
		int minv;
		int[] d = new int[n];
		int[] p = new int[n];
		color = new boolean[n];
		Arrays.fill(d, INF);
		Arrays.fill(p, -1);
		d[0] = 0;
		while (true) {
			minv = 1 << 24;
			u = -1;
			for (int i = 0; i < n; i++) {
