class Tree {
	int[][] leng;
	int[] reach;

	public Tree(int n) {
		leng = new int[n][n];
		reach = new int[n];
		for (int i = 0; i < n; i++)
			reach[i] = -1;
	}

	public int MinTree() {
		int min = Integer.MAX_VALUE;
		int xx = 0, yy = 0;
		for (int x = 0; x < leng.length; x++)
			for (int y = x + 1; y < leng[x].length; y++)
				if (leng[x][y] !=-1 && leng[x][y] < min) {
					xx = x;
					yy = y;
					min = leng[x][y];
				}
		reach[xx] = 0;
		reach[yy] = min;
		for (int i = 2; i < reach.length; i++)
			nextMin();

		int total = 0;
		for (int i = 0; i < reach.length; i++)
			total += reach[i];
		return total;
	}

	private void nextMin() {
		int min = Integer.MAX_VALUE;
		int xx = 0, yy = 0;
		for (int x = 0; x < leng.length; x++) {
			if (reach[x] == -1)
				continue;
			for (int y = 0; y < leng[x].length; y++) {
				if (reach[y] != -1||leng[x][y]==-1)
					continue;
				if (leng[x][y] < min) {
					xx = x;
					yy = y;
					min = leng[x][y];
				}
			}
		}
		reach[yy] = min;
	}

	public void setLeng(int x, int y, int length) {
		leng[x][y] = length;
	}

}

import java.io.IOException;
import java.io.InputStream;
import java.util.NoSuchElementException;

 class FS {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        } else {
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() {
        return hasNextByte() ? buffer[ptr++] : -1;
    }

    private boolean isPrintableChar(int c) {
        return 33 <= c && c <= 126;
    }

    private void skipUnprintable() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
    }

    public boolean hasNext() {
        skipUnprintable();
        return hasNextByte();
    }

    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public int nextInt() {
        return (int) nextLong();
    }

    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            } else if (b == -1 || !isPrintableChar(b)) {
                return minus ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
}
public class Main {
    static int[][] mm;
    static int[] minarray;
    static boolean[] pl;

   public static void main(String[] args) {
        FS fs = new FS();
        int n = fs.nextInt();
        mm = new int[n][n];
        minarray = new int[n];
        pl = new boolean[n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int k = fs.nextInt();
                mm[i][j] = k == -1 ? Integer.MAX_VALUE : k;
            }
        }
        pl[0] = true;
        int count = 0;
        int min = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            minarray[i] = mm[0][i];
        }
        for (int i = 0; i < n; i++) {
            int v = 0;
            for (int j = 0; j < n; j++) {
                if (!pl[j] &&minarray[j] < minarray[v]) {
                    v = j;
                }
            }
            if (v==0){
                break;
            }
            pl[v] = true;
            count += minarray[v];
            for (int j = 0; j < n; j++) {
                if (pl[j]){
                    continue;
                }
                minarray[j] = Math.min(mm[v][j], minarray[j]);
            }
        }
        System.out.println(count);
    }
}

