        adjWeight = new int[totalVertex][totalVertex];
        ifSettled = new Boolean[totalVertex];
        int i, j;
        for(i = 0; i < totalVertex; i ++) {
            ifSettled[i] = false;
            for(j = 0; j < totalVertex; j ++) {
                adjMatrix[i][j] = adjWeight[i][j] = 0;
            }
        }
        int w;
        for(i = 0; i < totalVertex; i ++) {
            for(j = 0; j < totalVertex; j ++) {
                w = in.nextInt();
                if(w > -1) {
                    adjMatrix[i][j] = 1;
                }
                adjWeight[i][j] = w;
            }
        }
