class MSTree {
	int[][] leng;
	int[] preLeng;
	int[] reachLeng;

	public MSTree(int n) {
		leng = new int[n][n];
		preLeng = new int[n];
		reachLeng = new int[n];
		for (int i = 1; i < n; i++)
			reachLeng[i] = Integer.MAX_VALUE;
	}

	public int getMinTree() {
		setMin(0);

		int total = 0;
		for (int i = 1; i < preLeng.length; i++)
			total += preLeng[i];
		return total;
	}

	private void setMin(int from) {
		for (int next = 0; next < leng.length; next++)
			if (leng[from][next] > 0) {
				int d = reachLeng[from] + leng[from][next];
				if (d < reachLeng[next]) {
					reachLeng[next] = d;
					preLeng[next] = leng[from][next];
					setMin(next);
				}
			}
	}

	public void setLeng(int x, int y, int length) {
		leng[x][y] = length;
	}

}

