	public int[] Dijkstra(int s) {
		int[] dist = new int[totalVertex];
		int[] previous = new int[totalVertex];

		for(int i = 1; i < totalVertex; i++) {
			dist[i] = Integer.MAX_VALUE;
			previous[i] = -1;
		}
		dist[s] = 0;

		LinkedList<Integer> settled = new LinkedList<Integer>();

		while(!settled.containsAll(getNeighbors(s))) {
			int u = getUnsettledNearest(dist);
			if(dist[u] == Integer.MAX_VALUE) {
				break;
			}
			for(int j = 0; j < totalVertex; j++) {
				int v = getUnsettledNearest(dist);
				ifSettled[v] = true;

				for (int x = 0; x < totalVertex; x++) {
					if (ifSettled[x] == false && adjMatrix[v][x] == 1) {
						dist[x] = Math.min(getWeight(v, x), dist[x]);
					}
				}
				settled.add(v);
			}
		}


		return dist;

	}

}

