						nextVisitFrom = from;
						nextVisitTo = to;
						min = mat[from][to];
					}
				}
			}
			target.remove(nextVisitTo);
			mst.add(nextVisitTo);
			cost += mat[nextVisitFrom][nextVisitTo];
		}
		System.out.println(cost);

	}

}

