			d[i]=Integer.MAX_VALUE;
			p[i]=-1;
		}
		d[0]=0;
		while(true){
			min=Integer.MAX_VALUE;
			u=-1;
			for(i=0;i<n;i++){
				if(min>d[i]&&check[i]!=1){
					u=i;
					min=d[i];
				}
			}
			if(u==-1)break;//finished
			check[u]=1;
			for(i=0;i<n;i++){
				if(check[i]!=1&&m[u][i]!=-1){
