                return o1.w<o2.w?-1:1;
            }
        });
        ArrayList<Set<Integer>> T = new ArrayList<>();
        int opt = 0;
        while(L.size()!=0){
            Node e = L.remove(0);
            int t1=-1,t2=-1;
            for(int i=0;i<T.size();i++){
                if(T.get(i).contains(e.v1)) t1 = i;
                if(T.get(i).contains(e.v2)) t2 = i;
            }
            if(t1==-1&&t2==-1){
