                opt+=e.w;
                if(t1==-1) T.get(t2).add(e.v1);
                else if(t2==-1)T.get(t1).add(e.v2);
                else{
                    T.get(t1).addAll(T.get(t2));
                    T.remove(t2);
                }
            }
