			str.append(" ");
			str.append(to);
			str.append(" ");
			str.append(cost);
			return str.toString();
		}
	}

	private static class EdgeComparator implements Comparator<Edge>{
		@Override
		public int compare(Edge o1, Edge o2) {
			return o1.cost - o2.cost; // IDの値に従い昇順で並び替えたい場合
			// return -(user1.getId() - user2.getId()); // IDの値に従い降順で並び替えたい場合
		}
