		return mv;
	}

	// implement the following
	public int[] Dijkstra(int x) {
		int[] map = new int[totalVertex];
		for (int i = 0; i < totalVertex; i++) {
			map[i] = Integer.MAX_VALUE;
		}

		map[x] = 0;
		ifSettled[x] = true;

		int set = x;
		boolean cow = true;
		LinkedList<Integer> neighbors;

		while (cow) {
			neighbors = getUnsettledNeighbors(set);
			for (int i : neighbors) {
				map[i] = Math.min(map[i], getWeight(set, i));
			}
			set = getUnsettledNearest(map);
			ifSettled[set] = true;
			cow = false;
			for (int i = 0; i < totalVertex; i++) {
				if (ifSettled[i] == false) {
					cow = true;
				}
			}
		}
		return map;
	}
}

