		PriorityQueue<Edge> que = new PriorityQueue<>((a, b) -> a.w- b.w);
		for(int i=0; i<n; i++) {
			for(int j=0; j<n; j++) {
				int w = sc.nextInt();
				if(i < j && w != -1) {
