class Tree
{
    private int[] p; //頂点iの親がp[i-1]
    public Tree(int n) //コンストラクタ
    {
        p = new int[n];
        for (int i = 0; i < n; i++) p[i] = i + 1;
    }
    public int GetParent(int a) //aの親を返す
    {
        return p[a - 1];
    }
    public void SetParent(int a, int b) //aの親をbに設定
    {
        p[a - 1] = b;
    }
    public int root(int a) //aのrootを求め、aの親にする
    {
        if (p[a - 1] == a) return a;
        return (p[a - 1] = root(p[a - 1]));
    }
    public bool IsSameSet(int a, int b) //aとbが同一グループに属するか
    {
        return root(a) == root(b);
    }
    public void unite(int a, int b) //aとbを同一グループにまとめる
    {
        p[root(a) - 1] = root(b);
    }
}
