    class Program
    {
        static readonly int INFTY = int.MaxValue;

        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());

            int[,] table = new int[n, n];

            for (int i = 0; i < n; i++)
            {
                int[] input = Array.ConvertAll(Console.ReadLine().Trim().Split(' '), int.Parse);

                for (int j = 0; j < n; j++)
                {
                    table[i, j] = input[j] == -1 ? INFTY : input[j];
                }
            }

            Console.WriteLine(Prim(table, n));
        }

        static int Prim(int[,] table, int n)
        {
            int i, nodeId, minCost;
            int[] minCostArr = new int[n];
            int[] parents = new int[n];
            Color[] colors = new Color[n];

            for (i = 0; i < n; i++)
            {
                minCostArr[i] = INFTY;
                parents[i] = -1;
            }

            minCostArr[0] = 0;

            while (true)
            {
                minCost = INFTY;
                nodeId = -1;

                for (i = 0; i < n; i++)
                {
                    if (colors[i] != Color.black && minCostArr[i] < minCost)
                    {
                        minCost = minCostArr[i];
                        nodeId = i;
                    }
                }

                if (minCost == INFTY) break;

                colors[nodeId] = Color.black;

                for (i = 0; i < n; i++)
                {
                    if (colors[i] != Color.black && table[nodeId, i] != INFTY)
                    {
                        if (table[nodeId, i] < minCostArr[i])
                        {
                            minCostArr[i] = table[nodeId, i];
                            parents[i] = nodeId;
                            colors[i] = Color.gray;
                        }
                    }
                }
            }

            int ret = 0;
            for (i = 0; i < n; i++)
            {
                if (parents[i] != -1) ret += table[i, parents[i]];
            }
            return ret;
        }
    }
