    public static void Main(string[] args)
    {
        //var exStdIn = new System.IO.StreamReader( "input.txt" );
        //System.Console.SetIn( exStdIn );

        int n = int.Parse(Console.ReadLine());

        var nodes = new Node[n];
        for (int i = 0; i < n; i++)
        {
            nodes[i] = new Node(i);
        }

        for (int i = 0; i < n; i++)
        {
            int[] val = Console.ReadLine().Trim().Split(' ').Select(x => int.Parse(x)).ToArray();
            for (int j = 0; j < n; j++)
            {
                if (val[j] != -1)
                {
                    nodes[i].Adj.Add(new Tuple<int, int>(j, val[j]));
                }
            }
        }

        // root
        nodes[0].ParentId = -1;

        int d = 0;
        while (true)
        {
            var queue = new Queue<int>();
            queue.Enqueue(0);
            for (int i = 0; i < n; i++)
            {
                nodes[i].Checked = false;
            }
            int addD = Bfs(nodes, queue);
            if (addD == -1)
            {
                break;
            }
            d += addD;
        }
        Console.WriteLine(d.ToString());
    }

    public static int Bfs(Node[] nodes, Queue<int> queue)
    {
        int d = -1;
        int parent = -1;
        int target = -1;
        while (queue.Count > 0)
        {
            var i = queue.Dequeue();
            nodes[i].Checked = true;
            for (int j = 0; j < nodes[i].Adj.Count; j++)
            {
                var child = nodes[nodes[i].Adj[j].Item1];
                if (child.Checked)
                {
                    continue;
                }
                if (child.ParentId < 0)
                {
                    if (d == -1 || nodes[i].Adj[j].Item2 < d)
                    {
                        d = nodes[i].Adj[j].Item2;
                        parent = i;
                        target = nodes[i].Adj[j].Item1;
                    }
                }
                else
                {
                    queue.Enqueue(nodes[i].Adj[j].Item1);
                }
                child.Checked = true;
            }
        }
        if (d != -1)
        {
            nodes[target].ParentId = parent;
            nodes[parent].Children.Add(target);
        }
        return d;
    }
}

