	class MinimunSpanningTree
	{
		public MinimunSpanningTree ( int[][] adjacencyArray )
		{
			this.Size = adjacencyArray.Length;

			this.AdjacencyArray = new int[Size][];

			for (int lp = 0; lp < Size; lp++)
			{
				this.AdjacencyArray[lp] = new int[Size];

				for (int lp2 = 0; lp2 < Size; lp2++)
				{
					this.AdjacencyArray[lp][lp2] =
						adjacencyArray[lp][lp2] != NotExist ? adjacencyArray[lp][lp2] : Infinity;
				}
			}
		}

		private int[][] AdjacencyArray { set; get; }
		private const int NotExist = -1;
		private const int Infinity = int.MaxValue;

		private int Size { set; get; }

		public int Prim ()
		{
			//initilize
			int[] visitState = new int[Size];
			const int Stay = 1;
			const int Visited = 2;

			int[] weight = Enumerable.Repeat (Infinity, Size).ToArray ();

			int[] parent = Enumerable.Repeat (NotExist, Size).ToArray ();

			//process
			weight[0] = 0;

			while (true)
			{
				int minCost = Infinity;
				int index = 0;

				for (int lp = 0; lp < Size; lp++)
				{
					if (visitState[lp] != Visited && weight[lp] < minCost)
					{
						minCost = weight[lp];
						index = lp;
					}
				}

				if (minCost == Infinity)
				{
					break;
				}

				visitState[index] = Visited;

				for (int lp = 0; lp < Size; lp++)
				{
					if (visitState[lp] != Visited && AdjacencyArray[index][lp] != Infinity)
					{
						if (AdjacencyArray[index][lp] < weight[lp])
						{
							weight[lp] = AdjacencyArray[index][lp];
							parent[lp] = index;
							visitState[lp] = Stay;
						}
					}
				}
			}

			int sum = 0;

			for (int lp = 0; lp < Size; lp++)
			{
				if (parent[lp] != NotExist)
				{
					sum += AdjacencyArray[lp][parent[lp]];
				}
			}

			return sum;
		}
	}
}

