        static void Show(int N, int[] d)
        {
            int ans = 0;
            for (int i = 0; i < N; i++) ans += d[i];
            Console.WriteLine(ans);
        }


        static void Prim(int N, int[,] g)
        {
            bool[] visit = new bool[N];

            int[] d = new int[N];
            for (int i = 0; i < N; i++) d[i] = INF;
            d[0] = 0;

            while (true)
            {
                int mincost = INF;
                int from = -1;

                for(int v = 0; v < N; v++)
                {
                    if(!visit[v] && d[v] < mincost)
                    {
                        mincost = d[v];
                        from = v;
                    }
                }

                if (from == -1) break;
                visit[from] = true;

                for (int to = 0; to < N; to++)
                {
                    if(!visit[to] && g[from, to] != -1 && g[from, to] < d[to])
                    {
                        d[to] = g[from, to];
                    }
                }

            }

            Show(N, d);
        }


        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());

            int[,] g = new int[N, N];

            for (int i = 0; i < N; i++)
            {
                string[] input = Console.ReadLine().Split(' ');
                for(int j = 0; j < N; j++)
                {
                    g[i, j] = int.Parse(input[j + 1]);
                }
            }            

            Prim(N, g);
        }
    }
}

