        G = new int[n, n];
        for (int i = 0; i < n; i++) {
            string[] input = Console.ReadLine().Split(' ');
            for(int j = 0; j < n; j++) {

                G[i, j] = (int.Parse(input[j+1])==-1)?INFTY:int.Parse(input[j+1]);
            }
        }
        MST();
    }

    public static void MST() {
        var d = Enumerable.Repeat(INFTY, n).ToArray();
        var parent = Enumerable.Repeat(-1, n).ToArray();
        var Color = Enumerable.Repeat("WHITE", n).ToArray();
        d[0] = 0;
        while (true) {
            int mincost = INFTY;
            int u = -1;
            for (int i = 0; i < n; i++) {
                if (Color[i] != "BLACK" && d[i] < mincost) {
                    mincost = d[i];
                    u = i;
                }
            }
            if (mincost == INFTY) {
                break;
            }
            Color[u] = "BLACK";
            for (int v = 0; v < n; v++) {
                if (Color[v] != "BLACK" && G[u, v] != INFTY) {
                    if (G[u,v] < d[v]) {
                        d[v] = G[u, v];
                        parent[v] = u;
                        Color[v] = "GRAY";
                    }
