static class Calculation {
    enum C {
        B, G, W
    }

    internal static int Calc(int n, int[,] m) {
        int[] d = Enumerable.Repeat(int.MaxValue, n).ToArray();
        int[] p = new int[n];   // prevtop
        C[] cs = Enumerable.Repeat(C.W, n).ToArray();


        int top = 0;  // Root
        d[top] = 0;

        while (true) {
            var minCost = int.MaxValue;
            for (int i = 0; i < n; i++) {
                if (minCost > d[i] && cs[i] != C.B) {
                    minCost = d[i];
                    top = i;
                }
            }

            if (minCost == int.MaxValue) {
                break;
            }

            cs[top] = C.B;

            for (int i = 0; i < n; i++) {
                if (cs[i] != C.B && m[top, i] < d[i]) {
                    p[i] = top;
                    d[i] = m[top, i];
                    cs[i] = C.G;
                }
            }
        }

        return d.Sum();

    }
}

