        private static int[] d;

        private static bool[] isVisited;
        static void Main(string[] args)
        {
            Program.n = int.Parse(Console.ReadLine());
            Program.d = new int[Program.n];
            Program.isVisited = new bool[Program.n];
            Program.neigborWeights = new int[Program.n, Program.n];
            for (int i = 0; i < Program.n; i++)
            {
                int[] tmpLine = Console.ReadLine()
                                        .Trim(' ')
                                        .Split(' ')
                                        .Select(s => int.Parse(s))
                                        .ToArray();
                for (int j = 0; j < Program.n; j++)
                {
                    Program.neigborWeights[i, j] = tmpLine[j];
                }
                Program.d[i] = (int)Math.Pow(10, 7);
            }
            Program.d[0] = 0;

            int minSumWeight = 0;
            MinHeap minHeap = new MinHeap(Program.n);
            while(minHeap.maxIndex >= 0)
            {
                int vertex = minHeap.Dequeue(Program.d);
                Program.isVisited[vertex] = true;
                minSumWeight += d[vertex];
                for (int i = 0; i < Program.n; i++)
                {
                    if
                    (   Program.neigborWeights[vertex, i] >= 0
                    &&  !Program.isVisited[i]
                    &&  Program.d[i] > Program.neigborWeights[vertex, i]
                    )
                    {
                        Program.d[i] = Program.neigborWeights[vertex, i];
