                color[i] = "WHITE";
            }
            d[0] = 0;

            int u=0;
            while (true)
            {
                int min = int.MaxValue;
                for (i = 0; i < n; i++)
                {
                    if (color[i] != "BLACK" && d[i] < min)
                    {
                        min = d[i];
                        u = i;
                    }
                }
                if (min == int.MaxValue)
                {
                    break;
