public class Program
{
	static int[] parent;
	static int[] rank;

	public static void Main()
	{
		int n = int.Parse(Console.ReadLine());
		int[,] A = new int[n,n];

		for(int i = 0; i < n; i++) {
			var cells = Console.ReadLine().Trim(" ".ToCharArray()).Split(" ".ToCharArray());

			for(int j = 0; j < n; j++) {
				A[i,j] = int.Parse(cells[j]);
			}
		}

		List<Side> S = new List<Side>();

		//?\?????¨?§???¨?????§?´???£???¨?\???????????\?????\?????????\?\?????£?????¨?????£???¨?£?????£?????\?????\?????£?????£?????£????
		for(int i = 0; i < n; i++) {
			for(int j = i +1; j < n; j++) {
				if(A[i,j] != -1) S.Add(new Side(i,j,A[i,j]));
			}
		}

		S.Sort((a,b) => a.len - b.len);

		InitializeUnionFind(n);
		int ans = 0;
		for(int i = 0; i < S.Count(); i++) {
			Side e = S[i];

			if(!Same(e.a, e.b)) {
				Unite(e.a, e.b);
				ans += e.len;
			}
		}

		Console.WriteLine(ans);
	}

	public static bool Same(int x, int y)
	{
		return (Find(x) == Find(y));
	}

	public static int Find(int x)
	{
		if(parent[x] == x) return x;
		else return parent[x] = Find(parent[x]);
	}

	public static void Unite(int x, int y)
	{
		x = Find(x);
		y = Find(y);

		if(x == y) return;

		if(rank[x] < rank[y]) {
			parent[x] = y;
		} else {
			parent[y] = x;

			if(rank[x] == rank[y]) rank[x]++;
		}
	}

	public static void InitializeUnionFind(int n)
	{
		parent = new int[n];
		rank = new int[n];

		for(int i = 0; i < n; i++) {
			parent[i] = i;
		}
	}
}

public class Side
{
	public int a { private set; get; }
	public int b { private set; get; }
	public int len { private set; get; }

	public Side (int v1, int v2, int v3)
	{
		a	= v1;
		b	= v2;
		len	= v3;
	}
}

