var n;
var g = [];
var p = [];
var r = [];

function init(){
	rep(g.length, function(i){
		p[i] = i;
		r[i] = 0;
	});
}

function find(i){
	return p[i] === i ? i : p[i] = find(p[i]);
}

function same(i, j){
	return find(i) === find(j);
}

function unite(i, j){
	var a = find(i);
	var b = find(j);

	if(a === b){
		return;
	}

	if(r[a] > r[b]){
		p[b] = a;
	}
	else{
		p[a] = b;
		if(r[a] === r[b]){
			++r[b];
		}
	}
}

