(function main() {
  const lines = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split('\n');
  const n = Number(lines.shift());
  const adj = lines.map((e, i) => e.trim().split(' ').map(n => n == -1 && Infinity || Number(n)));
  const range_n = Array.from(Array(n), (e, i) => i);

