class DisjointSet
  def initialize(size = nil)
    @rank = Array.new(size){0}
    @parent = []
    if size
      size.times do |i|
        @parent[i] = i
      end
    end
  end

  def same(x, y)
    return find(x) == find(y)
  end

  def unite(x, y)
    x = find(x)
    y = find(y)
    if @rank[x] > @rank[y]
      @parent[y] = x
    else
      @parent[x] = y
      @rank[y] += 1 if @rank[x] == @rank[y]
    end
  end

  def find(x)
    @parent[x] = find(@parent[x]) unless x == @parent[x] 
    return @parent[x]
  end
end

