from heapq import heappush, heappop

def prim(G):
    n = len(G)
    heap = []
    s = 0
    for v, c in G[s].items():
        heappush(heap, (c, v))
    added = set()
    added.add(s)
    cost = 0
    while len(added) < n:
        cu, u = heappop(heap)
        added.add(u)
        cost += cu
        for v, c in G[u].items():
            if v in added:
                continue
            heappush(heap, (c, v))
    return cost

