    let n: usize = iterator.next().unwrap().parse().unwrap();

    let mut m: Vec<Vec<isize>> = vec![vec![INFTY; n]; n];
    for i in 0..n {
        for j in 0..n {
            let weight: isize = iterator.next().unwrap().parse().unwrap();
            if weight != -1 {
                m[i][j] = weight;
            }
        }
    }

    let mut d: Vec<isize> = vec![INFTY; n];
    let mut color: Vec<Color> = vec![Color::WHITE; n];
    let mut p: Vec<isize> = vec![0; n];
    d[0] = 0;
    p[0] = -1;
    loop {
        let mut min_cost = INFTY;
        let mut u: usize = 0;
        for i in 0..n {
            if color[i] != Color::BLACK && d[i] < min_cost {
                min_cost = d[i];
                u = i;
            }
        }

        if min_cost == INFTY {
            break;
        }

        color[u] = Color::BLACK;

        for v in 0..n {
            if color[v] != Color::BLACK && m[u][v] != INFTY {
                if m[u][v] < d[v] {
                    d[v] = m[u][v];
                    p[v] = u as isize;
                    color[v] = Color::GRAY;
                }
            }
        }
    }

    let mut sum = 0;
    for i in 0..n {
        if p[i] != -1 {
            sum += m[i][p[i] as usize]
        }
    }
    return sum.to_string();
}

