#[derive(Debug)]
struct Kruskal<T> {
    edges: Vec<(usize, usize, T)>,
    zero: T,
    inf: T,
}

impl<T> Kruskal<T>
where
    T: Clone + Ord + std::ops::AddAssign,
{
    fn new(zero: T, inf: T) -> Self {
        Kruskal {
            edges: Vec::new(),
            zero: zero,
            inf: inf,
        }
    }

    fn add_edge(&mut self, from: usize, to: usize, cost: T) {
        self.edges.push((from, to, cost));
    }

    fn solve(&mut self) -> T {
        self.edges.sort_by(|&(_, _, ref c1), &(_, _,  ref c2)| c1.cmp(&c2));
        let mut uf = UnionFind::new(self.edges.len());
        let mut ret = self.zero.clone();
        for e in &self.edges {
            if !uf.same(e.0, e.1) {
                uf.unite(e.0, e.1);
                ret += e.2.clone();
            }
        }
        ret
    }
}

#[derive(Debug)]
struct UnionFind {
    par: Vec<usize>,
    rank: Vec<usize>,
}

impl UnionFind {
    fn new(n: usize) -> UnionFind {
        UnionFind {
            par: (0..n).collect(),
            rank: vec![0; n],
        }
    }

    fn find(&mut self, x: usize) -> usize {
        let par = self.par[x];
        if par != x {
            self.par[x] = self.find(par);
        }
        self.par[x]
    }

    fn unite(&mut self, x: usize, y: usize) {
        let x = self.find(x);
        let y = self.find(y);
        if x == y {
            return;
        }

        let rx = self.rank[x];
        let ry = self.rank[y];
        if rx < ry {
            self.par[x] = y;
        } else {
            self.par[y] = x;
            if rx == ry {
                self.rank[x] += 1;
            }
        }
    }

    fn same(&mut self, x: usize, y: usize) -> bool {
        self.find(x) == self.find(y)
    }
}
